// --- SOBREESCRITURA GLOBAL DE ALERTA PARA USAR EL MODAL PREMIUM ---
window.alert = function(message) {
    let type = 'warning';
    let title = 'ATENCIÓN';
    let cleanMessage = String(message || '');

    if (cleanMessage.includes('✅')) {
        type = 'success';
        title = '¡ÉXITO!';
        cleanMessage = cleanMessage.replace(/✅/g, '').trim();
    } else if (cleanMessage.includes('❌') || cleanMessage.includes('🚨') || cleanMessage.toLowerCase().includes('error')) {
        type = 'error';
        title = 'ERROR';
        cleanMessage = cleanMessage.replace(/[❌🚨]/g, '').trim();
    } else if (cleanMessage.includes('⚠️') || cleanMessage.includes('🚧') || cleanMessage.includes('🏗️')) {
        type = 'warning';
        title = 'ADVERTENCIA';
        cleanMessage = cleanMessage.replace(/[⚠️🚧🏗️]/g, '').trim();
    } else if (cleanMessage.includes('📦') || cleanMessage.includes('📡') || cleanMessage.includes('☁️') || cleanMessage.includes('🔒')) {
        type = 'info';
        title = 'INFORMACIÓN';
        cleanMessage = cleanMessage.replace(/[📦📡☁️🔒]/g, '').trim();
    }

    cleanMessage = cleanMessage.replace(/^[:!\s\-]+/, '');
    showPremiumAlert(title, cleanMessage, type);
};

const VERSION = '29.0156';
const CACHE_KEY = `logistics_v24_prod_`;
const DB_TASKS_KEY = 'almacenaje_tasks_history_v1';
console.log(`[PULSE] Engine v${VERSION} Initialized`);

// --- LOGICA DE FECHA OPERATIVA (Turno Noche) ---
const getTaskTotalAvance = (t) => {
    if (!t) return 0;
    let sum = 0;
    (t.items || []).forEach(art => {
        (art.items || []).forEach(i => {
            const ubi = String(i.ubi || '').toUpperCase().trim();
            const isBuffer = ubi.startsWith('CDBUFFER') && !ubi.startsWith('CDBUFFER-C');
            if (isBuffer) {
                if (i.avance !== undefined && i.avance !== null) {
                    sum += parseFloat(i.avance) || 0;
                } else if (t.status === 'Finalizado') {
                    sum += parseFloat(i.qty) || 0;
                }
            }
        });
    });
    return sum;
};

/** Deja una categoría en formato legible: '08 ACCESORIES' → 'Accesories'. */
const etiquetaCategoria = (v) => {
    const s = String(v || '').trim().replace(/^\d{1,2}[\s.-]+/, '');
    return s ? s.charAt(0).toUpperCase() + s.slice(1).toLowerCase() : '';
};

/**
 * Categoría de una tarea en sus dos niveles:
 *   familia → columna C del Maestro (G. Gender)
 *   detalle → columna D del Maestro (Gender RIMS)
 *
 * Las tareas antiguas guardaban un solo campo `gender` que a veces traía el valor de
 * una columna y a veces el de la otra, según la versión del sistema que las creó. Se
 * distingue por el prefijo numérico: los Gender RIMS vienen numerados, las familias no.
 *
 * Si la tarea junta varios artículos, la categoría se resuelve así:
 *   todos el mismo detalle           → ese detalle
 *   distinto detalle, misma familia  → la familia
 *   distinta familia                 → la familia con más unidades, marcada como mixta
 */
const getTaskCategoria = (t) => {
    const vacio = { familia: '', detalle: '', mixta: false, etiqueta: 'Sin categoría', etiquetaCorta: 'Sin categoría' };
    if (!t || !Array.isArray(t.items) || t.items.length === 0) return vacio;

    const familias = new Map(); // familia → unidades
    const detalles = new Map(); // detalle  → unidades
    const porSku = indexarMaestro().porSku;

    t.items.forEach(art => {
        const unidades = parseFloat(art.bufferQty) || 0;
        let campoDetalle = art.genderRims;
        let campoFamilia = art.gender;

        // Las tareas creadas antes de que el Gender RIMS viajara al servidor vuelven sin él.
        // Se completa con el Maestro, buscando por SKU, para no perder esas tareas del histórico.
        if (metasService.esCategoriaVacia(campoDetalle) && art.sku7) {
            const delMaestro = porSku.get(String(art.sku7).trim().substring(0, 7));
            if (delMaestro) {
                campoDetalle = delMaestro.detalle;
                if (metasService.esCategoriaVacia(campoFamilia)) campoFamilia = delMaestro.familia;
            }
        }

        // Campo explícito de Gender RIMS (tareas nuevas)
        if (!metasService.esCategoriaVacia(campoDetalle)) {
            const d = String(campoDetalle).trim().toUpperCase();
            detalles.set(d, (detalles.get(d) || 0) + unidades);
        }

        if (!metasService.esCategoriaVacia(campoFamilia)) {
            const g = String(campoFamilia).trim().toUpperCase();
            // En tareas viejas este campo podía traer el Gender RIMS en vez de la familia
            if (metasService.pareceDetalle(g)) {
                if (!detalles.has(g)) detalles.set(g, (detalles.get(g) || 0) + unidades);
            } else {
                familias.set(g, (familias.get(g) || 0) + unidades);
            }
        }
    });

    if (familias.size === 0 && detalles.size === 0) return vacio;

    const dominante = (mapa) => [...mapa.entries()].sort((a, b) => b[1] - a[1])[0][0];

    const familia = familias.size > 0 ? dominante(familias) : '';
    const detalle = detalles.size === 1 ? [...detalles.keys()][0] : '';
    const mixta = familias.size > 1;

    const partes = [];
    if (familia) partes.push(etiquetaCategoria(familia));
    if (detalle) partes.push(etiquetaCategoria(detalle));
    const etiqueta = partes.join(' · ') || 'Sin categoría';
    const etiquetaCorta = etiquetaCategoria(familia) || etiquetaCategoria(detalle) || 'Sin categoría';

    return { familia, detalle, mixta, etiqueta, etiquetaCorta, detalles: [...detalles.keys()] };
};

/** Meta de u/h y tamaño de tarea vigentes para una tarea, según su categoría y su fecha. */
const getTaskMeta = (t) => {
    const { familia, detalle } = getTaskCategoria(t);
    return metasService.resolverMeta(detalle, familia, t && t.fecha);
};

/* ── EL MAESTRO DE ARTÍCULOS ──────────────────────────────────────────────
   El Maestro se publica UNA vez desde Configuración → Archivos Nube y todas las
   PC lo bajan de ahí. Antes cada PC tenía que subirlo por su cuenta: la que no lo
   hacía se quedaba sin categorías, y por eso 98 tareas quedaron sin clasificar.

   La bajada es barata: primero se consulta una ficha de unos pocos bytes con la
   fecha y la cantidad de artículos publicados. Si coincide con la copia que este
   navegador ya tiene guardada, no se baja nada más.
*/

/** Un solo viaje aunque lo pidan dos pantallas a la vez. */
let _maestroPromesa = null;
/** ¿Ya se contrastó contra la nube en esta sesión? */
let _maestroVerificado = false;

const hayMaestroEnMemoria = () => (dataStore.articulos || []).length > 0
    || (dataStore.analisis_sku_maestro || []).length > 0;

/**
 * Analisis SKU sube el Maestro por su propia puerta ('analisis_sku_maestro') y
 * lee de ahi. Es el MISMO archivo con las mismas columnas: indexarMaestro() y el
 * Layout ya los tratan como equivalentes. Se le presta la copia de la nube para
 * que tampoco tenga que subirlo, pero solo si esta vacio: si el usuario cargo
 * uno a mano, manda el suyo.
 */
const compartirMaestroConAnalisisSku = (pisar = false) => {
    const maestro = dataStore.articulos;
    if (!Array.isArray(maestro) || maestro.length === 0) return;
    // Cuando la copia viene de la nube se pisa lo que hubiera: si no, un
    // 'analisis_sku_maestro' viejo guardado en esta PC seguiría usándose.
    if (!pisar && (dataStore.analisis_sku_maestro || []).length > 0) return;
    dataStore.analisis_sku_maestro = maestro;
};

/**
 * De dónde salió el Maestro que está cargado y qué copia es. Se muestra antes de generar
 * tareas: las marcas de cada tarea salen de acá, y hasta ahora nadie tenía forma de saber
 * con cuál estaba trabajando.
 *   origen 'nube'    -> el publicado, que es el que usa todo el mundo
 *   origen 'local'   -> el que quedó guardado en ESTA PC porque la nube no respondió
 *   origen 'ninguno' -> no hay Maestro; no se pueden generar tareas
 */
let _maestroEstado = { origen: 'ninguno', filas: 0, fecha: '', usuario: '' };
export const maestroEnUso = () => _maestroEstado;

const rescatarMaestro = async (forzar = false) => {
    // Contrastar contra la nube es barato: traerMaestroPublicado() pide primero una ficha de
    // unos pocos bytes y solo baja el archivo grande si de verdad cambió.
    //
    // Con `forzar` se vuelve a mirar aunque ya se haya verificado en esta sesión. Sin eso,
    // una pestaña abierta desde las 19:00 seguía usando el Maestro de esa hora toda la noche:
    // si a las 00:37 se publicaba otro, esta PC generaba tareas con marcas viejas mientras la
    // de al lado las generaba con las nuevas, y ninguna de las dos se enteraba.
    if (!forzar && _maestroVerificado && hayMaestroEnMemoria()) { compartirMaestroConAnalisisSku(); return true; }
    if (_maestroPromesa && !forzar) return _maestroPromesa;
    if (forzar) { _maestroPromesa = null; _maestroVerificado = false; }

    _maestroPromesa = (async () => {
        try {
            const r = await traerMaestroPublicado();
            if (r.filas > 0) {
                _maestroVerificado = true;
                const f = r.ficha || {};
                _maestroEstado = { origen: 'nube', filas: r.filas, fecha: f.fecha || '', usuario: f.usuario || '—' };
                console.log(`[Maestro] ${r.filas.toLocaleString('es-PE')} filas (${r.origen})`);
                compartirMaestroConAnalisisSku(true);
                return true;
            }
        } catch (e) {
            console.warn('[Maestro] no se pudo traer el publicado:', e && e.message);
        }

        // Todavía no hay nada publicado, o el servidor no responde: se usa lo que
        // haya quedado guardado en esta PC de una carga anterior.
        try {
            const local = dataStore.articulos && dataStore.articulos.length
                ? dataStore.articulos : await getAreaData('articulos');
            if (Array.isArray(local) && local.length > 0) {
                dataStore.articulos = local;
                _maestroEstado = { origen: 'local', filas: local.length, fecha: '', usuario: '' };
                console.log(`[Maestro] ${local.length.toLocaleString('es-PE')} filas (solo de esta PC)`);
                compartirMaestroConAnalisisSku();
                return true;
            }
        } catch (e) { /* tampoco estaba */ }

        _maestroEstado = { origen: 'ninguno', filas: 0, fecha: '', usuario: '' };
        return false;
    })();

    const listo = await _maestroPromesa;
    // Si falló, que el próximo intento pueda volver a probar
    if (!listo) _maestroPromesa = null;
    return listo;
};

/* Recordar de qué Gender cuelga cada categoría, para poder mostrarlo aunque en
   esa sesión el Maestro no esté cargado. Es solo una ayuda visual. */
const MEMORIA_PADRES = 'config_metas_padres_v1';

const leerPadresRecordados = () => {
    try {
        const crudo = JSON.parse(localStorage.getItem(MEMORIA_PADRES) || '{}');
        // Una versión anterior lo guardaba como lista de pares (un Map serializado). Se
        // acepta esa forma para no perder lo aprendido en los navegadores que ya la tienen.
        if (Array.isArray(crudo)) return Object.fromEntries(crudo.filter(p => Array.isArray(p) && p.length === 2));
        return (crudo && typeof crudo === 'object') ? crudo : {};
    } catch (e) { return {}; }
};

const recordarPadres = (padres) => {
    try {
        const guardado = leerPadresRecordados();
        Object.entries(padres).forEach(([det, fam]) => { if (fam) guardado[det] = fam; });
        const nuevo = JSON.stringify(guardado);
        // Se reescribe también cuando lo guardado venía en el formato viejo, así se corrige solo
        if (localStorage.getItem(MEMORIA_PADRES) !== nuevo) localStorage.setItem(MEMORIA_PADRES, nuevo);
    } catch (e) { /* sin espacio o en modo privado: se sigue sin recordar */ }
};

/**
 * Todo lo que se necesita del Maestro, armado UNA sola vez por carga: recorrer
 * 29 mil filas en cada fila de una tabla dejaría la pantalla trabada.
 * Columna B = SKU, columna C = G. Gender (familias), columna D = Gender RIMS (categorías).
 */
// Marca de "todavía no se armó nunca". Tiene que ser un valor que no pueda salir del
// dataStore: con null, la primera llamada sin Maestro cargado creía que ya estaba armado
// y devolvía null, y quien pidiera .padres reventaba.
const SIN_INDEXAR = Symbol('maestro sin indexar');
let _maestroIndexado = { fuente: SIN_INDEXAR, datos: null };

const indexarMaestro = () => {
    const maestro = (dataStore.articulos || []).length ? dataStore.articulos
        : (dataStore.analisis_sku_maestro || []).length ? dataStore.analisis_sku_maestro
        : null;
    // Se compara la referencia, no el contenido: si es el mismo arreglo, ya está armado
    if (_maestroIndexado.fuente === maestro) return _maestroIndexado.datos;

    const porSku = new Map();
    const familias = new Set();
    const detalles = new Set();
    const padres = {};

    (maestro || []).forEach(row => {
        if (!row) return;
        const raw = Array.isArray(row) ? row : Object.values(row);

        const sku = String(getCol(row, ['CodArticulo', 'SKU', 'Articulo']) || raw[1] || '').trim().substring(0, 7);
        const fam = String(getCol(row, ['G. Gender', 'G Gender', 'GENDER']) || raw[2] || '').trim().toUpperCase();
        const det = String(getCol(row, ['Gender RIMS', 'GENDERRIMS', 'GENDER_RIMS']) || raw[3] || '').trim().toUpperCase();

        // Cuando el Excel llega como arreglos, la fila de títulos entra como una fila más.
        // Se reconoce porque trae el NOMBRE de la columna en vez de un valor.
        if (fam.includes('GENDER') || det.includes('GENDER') || det.includes('RIMS')) return;

        if (sku && !porSku.has(sku)) porSku.set(sku, { familia: fam, detalle: det });
        if (!metasService.esCategoriaVacia(fam) && !metasService.pareceDetalle(fam)) familias.add(fam);
        if (!metasService.esCategoriaVacia(det)) {
            detalles.add(det);
            // De qué Gender cuelga la categoría: '01 MEN' → 'FOOTWEAR'
            if (!padres[det] && fam && !metasService.pareceDetalle(fam)) padres[det] = fam;
        }
    });

    const datos = {
        porSku,
        familias: [...familias].sort(),
        detalles: [...detalles].sort(),
        padres,
        filas: (maestro || []).length
    };
    _maestroIndexado = { fuente: maestro, datos };
    recordarPadres(padres);
    return datos;
};

/** Catálogo de categorías del Maestro vigente. */
const getCatalogoMaestro = () => {
    const d = indexarMaestro();
    return { familias: d.familias, detalles: d.detalles, padres: d.padres };
};

/** Gender (familia) del que cuelga una categoría, según el Maestro o lo recordado antes. */
const getPadreDe = (detalle) => {
    const d = String(detalle || '').trim().toUpperCase();
    if (!d) return '';
    return indexarMaestro().padres[d] || leerPadresRecordados()[d] || '';
};

/** Minutos trabajados en una tarea, descontando el break de 23:00 a 23:50. */
const getTaskMinutos = (t) => {
    if (!t || !t.inicio || !t.termino) return 0;
    const s = new Date(t.inicio);
    let e = new Date(t.termino);
    if (e < s) e = new Date(e.getTime() + 86400000);
    const sd = s.getHours() < 12 ? new Date(s.getTime() - 43200000) : s;
    const bS = new Date(sd.getFullYear(), sd.getMonth(), sd.getDate(), 23, 0, 0);
    const bE = new Date(sd.getFullYear(), sd.getMonth(), sd.getDate(), 23, 50, 0);
    const solape = Math.max(0, Math.min(e, bE) - Math.max(s, bS));
    return Math.max(0, Math.floor(((e - s) - solape) / 60000));
};

/**
 * Base común de los 3 reportes de KPI: una fila por tarea finalizada dentro del rango,
 * ya con su meta resuelta, su rendimiento y su desviación en unidades.
 */
const buildKpiDataset = (tasks, desde, hasta) => {
    const filas = [];
    (tasks || []).forEach(t => {
        if (!t || t.status !== 'Finalizado') return;
        // POR LA JORNADA EN QUE SE TRABAJO, no por la fecha de la ola.
        const diaTarea = diaOperativoDeTarea(t);
        if (!(diaTarea >= desde && diaTarea <= hasta)) return;

        const mins = getTaskMinutos(t);
        const qty = getTaskTotalAvance(t);
        const cat = getTaskCategoria(t);
        const meta = getTaskMeta(t);
        const uph = mins > 0 ? (qty / mins) * 60 : 0;
        // Tiempo que la tarea tenía permitido: el recorrido fijo (ir al buffer, ubicar el
        // artículo, volver) más lo que toma mover la cantidad al ritmo de la meta. Sin ese
        // recorrido, una tarea de 20 pares tendría 4 minutos y saldría reprobada siempre.
        const tiempoBase = meta.tiempoBase || 0;
        const minutosEsperados = tiempoBase + (meta.metaUph > 0 ? (qty / meta.metaUph) * 60 : 0);
        // Y al revés: de los minutos gastados, los que quedaron para mover mercadería
        const minutosUtiles = Math.max(0, mins - tiempoBase);
        const esperado = meta.metaUph * (minutosUtiles / 60);
        const usuarios = [t.u1, t.u2].filter(u => u && u !== '---');

        filas.push({
            id: t.id,
            // El dia que cuenta es el trabajado: de aca cuelgan la tabla KPI,
            // los graficos de tendencia y el filtro por dia.
            fecha: diaTarea,
            marca: marcaNormalizada(t.marca) || 'S/M',
            usuarios,
            grupo: usuarios.join(' + ') || '---',
            qty,
            mins,
            uph,
            metaUph: meta.metaUph,
            tiempoBase,
            minutosEsperados,
            esperado,
            desviacion: qty - esperado,
            // 100% = terminó justo en el tiempo permitido; más de 100% = le sobró tiempo
            pct: mins > 0 ? (minutosEsperados / mins) * 100 : 0,
            categoria: cat.etiqueta,
            familia: cat.familia,
            detalle: cat.detalle,
            etiquetaCorta: cat.etiquetaCorta,
            origenMeta: meta.origen,
            mixta: cat.mixta,
            ok: mins > 0 && mins <= minutosEsperados,
            inicio: t.inicio,
            termino: t.termino
        });
    });
    return filas;
};

/** hh:mm a partir de minutos. */
const fmtHM = (mins) => `${Math.floor(mins / 60).toString().padStart(2, '0')}:${(mins % 60).toString().padStart(2, '0')}`;

/** Color del semáforo de 3 niveles según el % de meta alcanzado. */
const colorPorPct = (pct) => pct >= 100 ? '#22c55e' : pct >= 85 ? '#f59e0b' : '#ef4444';

const mediana = (arr) => {
    if (!arr || !arr.length) return 0;
    const s = [...arr].sort((a, b) => a - b);
    const m = Math.floor(s.length / 2);
    return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

/** Porcentaje del equipo que queda por debajo de este valor. */
const percentilDe = (valor, todos) => {
    if (!todos || todos.length < 2) return 100;
    return Math.round((todos.filter(v => v < valor).length / (todos.length - 1)) * 100);
};

/* ============================================================================
   INICIO: comparativa de la semana en curso contra la anterior
   ============================================================================ */

/** Fecha a YYYY-MM-DD en hora LOCAL (toISOString daría el día anterior de noche). */
const aISO = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

/** Lunes de la semana a la que pertenece una fecha. */
const lunesDe = (fecha) => {
    const d = new Date(fecha.getFullYear(), fecha.getMonth(), fecha.getDate());
    d.setDate(d.getDate() - ((d.getDay() + 6) % 7));   // getDay(): 0 = domingo
    return d;
};

/**
 * Semana en curso y el MISMO tramo de la semana anterior.
 *
 * Comparar un lunes-a-jueves contra una semana completa inventaría una caída del
 * 40% que no existe, así que la semana pasada se corta en el mismo día.
 */
const rangoSemanas = (hoy = new Date()) => {
    const desdeEsta = lunesDe(hoy);
    const hoySinHora = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate());
    const diasCorridos = Math.round((hoySinHora - desdeEsta) / 86400000);

    const desdePasada = new Date(desdeEsta);
    desdePasada.setDate(desdePasada.getDate() - 7);
    const hastaPasada = new Date(desdePasada);
    hastaPasada.setDate(hastaPasada.getDate() + diasCorridos);

    return {
        desdeEsta, hastaEsta: hoySinHora, desdePasada, hastaPasada, diasCorridos,
        estaDesde: aISO(desdeEsta), estaHasta: aISO(hoySinHora),
        pasadaDesde: aISO(desdePasada), pasadaHasta: aISO(hastaPasada)
    };
};

/**
 * Unidades de UNA tarea repartidas por G. Gender (columna C del Maestro).
 *
 * Usa exactamente la misma regla que getTaskTotalAvance —solo ubicaciones
 * CDBUFFER que no sean CDBUFFER-C, y 'avance' cuando existe— para que la suma
 * de las categorías cuadre con el total que muestra el resto del sistema.
 */
const unidadesPorGender = (t) => {
    const out = new Map();
    if (!t) return out;

    (t.items || []).forEach(art => {
        if (!art) return;
        const g = String(art.gender || '').trim().toUpperCase() || 'SIN CATEGORÍA';
        let sum = 0;
        (art.items || []).forEach(i => {
            const ubi = String((i && i.ubi) || '').toUpperCase().trim();
            if (!ubi.startsWith('CDBUFFER') || ubi.startsWith('CDBUFFER-C')) return;
            if (i.avance !== undefined && i.avance !== null) sum += parseFloat(i.avance) || 0;
            else if (t.status === 'Finalizado') sum += parseFloat(i.qty) || 0;
        });
        if (sum) out.set(g, (out.get(g) || 0) + sum);
    });
    return out;
};

/**
 * Todo lo que necesita la pantalla de Inicio para un rango de fechas.
 * `filas` son las de buildKpiDataset (ya traen meta, minutos y esperado).
 */
const resumenSemana = (tasks, desde, hasta, filtroUsuario = null) => {
    let filas = buildKpiDataset(tasks, desde, hasta);
    if (filtroUsuario) filas = filas.filter(r => r.usuarios.includes(filtroUsuario));

    const idsValidos = new Set(filas.map(r => r.id));
    const porGender = new Map();
    const porDia = new Map();

    (tasks || []).forEach(t => {
        if (!t || !idsValidos.has(t.id)) return;
        // Se archiva por el DÍA TRABAJADO, no por el de la ola.
        const dTarea = diaOperativoDeTarea(t);
        unidadesPorGender(t).forEach((u, g) => {
            porGender.set(g, (porGender.get(g) || 0) + u);
            porDia.set(dTarea, (porDia.get(dTarea) || 0) + u);
        });
    });

    const qty = filas.reduce((a, r) => a + r.qty, 0);
    const mins = filas.reduce((a, r) => a + r.mins, 0);
    const esperado = filas.reduce((a, r) => a + r.esperado, 0);
    const diasActivos = new Set(filas.map(r => r.fecha));

    return {
        filas, porGender, porDia,
        tareas: filas.length,
        qty, mins,
        horas: mins / 60,
        uph: mins > 0 ? (qty / mins) * 60 : 0,
        cumplimiento: esperado > 0 ? (qty / esperado) * 100 : 0,
        diasActivos,
        dias: diasActivos.size,
        personas: new Set(filas.flatMap(r => r.usuarios)).size,
        porDiaActivo: diasActivos.size > 0 ? qty / diasActivos.size : 0
    };
};

/**
 * Número de semana ISO (las que empiezan en lunes). Es el "SEM 31" del tablero.
 * Se calcula sobre el jueves de esa semana, que es lo que define a qué año
 * pertenece cuando la semana cae a caballo entre diciembre y enero.
 */
const semanaISO = (fecha) => {
    const d = new Date(Date.UTC(fecha.getFullYear(), fecha.getMonth(), fecha.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    const inicioAno = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    return Math.ceil((((d - inicioAno) / 86400000) + 1) / 7);
};

/** Los 7 días (lunes a domingo) de la semana que empieza en `lunes`. */
const diasDeSemana = (lunes) => {
    const out = [];
    for (let i = 0; i < 7; i++) {
        const d = new Date(lunes);
        d.setDate(d.getDate() + i);
        out.push(d);
    }
    return out;
};

/**
 * {G. Gender → {fecha → unidades}} de las tareas finalizadas en el rango.
 * Es la materia prima de la tabla de días: una fila por semana y una columna
 * por día, para cada categoría.
 */
const unidadesPorGenderYDia = (tasks, desde, hasta) => {
    const mapa = new Map();
    (tasks || []).forEach(t => {
        if (!t || t.status !== 'Finalizado' || !t.fecha) return;
        // Por la jornada en que se trabajo, no por la fecha de la ola.
        const dTarea = diaOperativoDeTarea(t);
        if (dTarea < desde || dTarea > hasta) return;
        unidadesPorGender(t).forEach((u, g) => {
            if (!mapa.has(g)) mapa.set(g, new Map());
            const porDia = mapa.get(g);
            // Se archiva por el DIA TRABAJADO, no por el de la ola. Arreglar el filtro
            // y dejar esta linea con t.fecha era el error: la tarea pasaba el filtro del
            // jueves y se guardaba en el miercoles, asi que el jueves salia vacio.
            porDia.set(dTarea, (porDia.get(dTarea) || 0) + u);
        });
    });
    return mapa;
};

/**
 * {marca → unidades} de las tareas finalizadas en un rango.
 * La marca vive en la tarea, no en el artículo, así que se toma el total de la
 * tarea con la regla de siempre (getTaskTotalAvance).
 */
const unidadesPorMarca = (tasks, desde, hasta, soloGender = null) => {
    const mapa = new Map();
    (tasks || []).forEach(t => {
        if (!t || t.status !== 'Finalizado' || !t.fecha) return;
        // Por la jornada en que se trabajo, no por la fecha de la ola.
        const dTarea = diaOperativoDeTarea(t);
        if (dTarea < desde || dTarea > hasta) return;
        const m = marcaNormalizada(t.marca) || 'Sin marca';
        // Con `soloGender` se cuenta únicamente esa categoría de la tarea, no su
        // total: una tarea puede mezclar artículos de varios G. Gender.
        const u = soloGender ? (unidadesPorGender(t).get(soloGender) || 0)
                             : getTaskTotalAvance(t);
        if (u) mapa.set(m, (mapa.get(m) || 0) + u);
    });
    return mapa;
};

/** Variación porcentual de a respecto de b, tolerando el cero. */
const variacion = (a, b) => {
    if (b > 0) return ((a - b) / b) * 100;
    if (a > 0) return null;    // null = "nuevo", no hay contra qué comparar
    return 0;
};

/**
 * Estadística por operario a partir de las tareas de sus grupos.
 * Las unidades son las del grupo completo, que es lo comparable contra la meta
 * (que también es de grupo). El detalle por día queda listo para desplegar.
 */
const buildStatsOperarios = (filas) => {
    const m = new Map();
    (filas || []).forEach(r => {
        if (r.mins <= 0) return;
        r.usuarios.forEach(u => {
            const c = m.get(u) || { user: u, qty: 0, mins: 0, tareas: 0, enMeta: 0, pcts: [], uphs: [], porDia: new Map() };
            c.qty += r.qty;
            c.mins += r.mins;
            c.tareas++;
            if (r.ok) c.enMeta++;
            c.pcts.push(r.pct);
            c.uphs.push(r.uph);
            const d = c.porDia.get(r.fecha) || { fecha: r.fecha, qty: 0, mins: 0, meta: 0, tareas: 0 };
            d.qty += r.qty; d.mins += r.mins; d.meta += r.esperado; d.tareas++;
            c.porDia.set(r.fecha, d);
            m.set(u, c);
        });
    });

    const lista = [...m.values()].map(c => {
        const prom = c.pcts.reduce((a, b) => a + b, 0) / c.pcts.length;
        const varianza = c.pcts.reduce((a, p) => a + Math.pow(p - prom, 2), 0) / c.pcts.length;
        const cv = prom > 0 ? (Math.sqrt(varianza) / prom) * 100 : 0;
        return {
            ...c,
            promPct: prom,
            avgUph: c.mins > 0 ? (c.qty / c.mins) * 60 : 0,
            minUph: Math.min(...c.uphs),
            medUph: mediana(c.uphs),
            maxUph: Math.max(...c.uphs),
            consistencia: Math.max(0, 100 - cv),
            pctEnMeta: c.tareas > 0 ? (c.enMeta / c.tareas) * 100 : 0,
            dias: [...c.porDia.values()].sort((a, b) => b.fecha.localeCompare(a.fecha))
        };
    });

    const todosProm = lista.map(x => x.promPct);
    lista.forEach(x => { x.percentil = percentilDe(x.promPct, todosProm); });
    return lista;
};

/**
 * Resumen por jornada. A diferencia del resto del módulo, acá SÍ entran las tareas que no
 * se finalizaron: son las que explican por qué el buffer no baja aunque el equipo cumpla meta.
 *
 * Ojo con `unidPend`: NO se puede sumar entre días. Si una tarea no se ejecuta, su mercadería
 * sigue en el buffer y al día siguiente el sistema la vuelve a convertir en tarea nueva, así
 * que el mismo SKU aparece repetido en varias jornadas.
 */
/**
 * EN QUÉ DÍA CUENTA UNA TAREA.
 *
 * Una FINALIZADA cuenta en la jornada en que se trabajó; una que sigue pendiente, en el día
 * en que nació, porque todavía no se trabajó en ninguno.
 *
 * Acá se agrupaba todo por `t.fecha`, la fecha en que se generó la ola. Como una tarea podía
 * vivir 48 horas, el turno de hoy trabajando una tarea de ayer sumaba al día de ayer: el
 * 07-ago-2026 Daniel abrió el detalle del jueves y le decía CERO en footwear, con el turno
 * habiendo movido más de trece mil pares esa noche. Es el mismo defecto que ya se corrigió en
 * el reporte de Marcas, y la regla que se aplica es la misma.
 */
const diaOperativoDeTarea = (t) => diaOperativoCompartido(t, (m) => jornadaService.fechaLogicaDe(m));

const buildJornadas = (tasksAll, desde, hasta, familia) => {
    const enRango = (tasksAll || []).filter(t => {
        const d = diaOperativoDeTarea(t);
        return d && d >= desde && d <= hasta;
    });
    const delFiltro = (!familia || familia === 'TODAS')
        ? enRango
        : enRango.filter(t => getTaskCategoria(t).familia === familia);

    const dias = [...new Set(delFiltro.map(diaOperativoDeTarea))].sort((a, b) => b.localeCompare(a));

    return dias.map(fecha => {
        const dd = delFiltro.filter(t => diaOperativoDeTarea(t) === fecha);
        const fin = dd.filter(t => t.status === 'Finalizado');
        const asignadas = dd.filter(t => t.status === 'Asignado');
        const creadas = dd.filter(t => t.status !== 'Finalizado' && t.status !== 'Asignado');

        let qty = 0, meta = 0, mins = 0, ok = 0, sinHora = 0;
        fin.forEach(t => {
            const m = getTaskMinutos(t);
            const a = getTaskTotalAvance(t);
            const metaTarea = getTaskMeta(t);
            const metaUph = metaTarea.metaUph;
            const tBase = metaTarea.tiempoBase || 0;
            qty += a; mins += m;
            if (m > 0) {
                // Mismo criterio que el KPI: se descuenta el recorrido antes de exigir la meta
                meta += metaUph * (Math.max(0, m - tBase) / 60);
                if (m <= tBase + (metaUph > 0 ? (a / metaUph) * 60 : 0)) ok++;
            } else {
                sinHora++; // finalizada sin inicio o término marcado: no se puede medir
            }
        });

        const grupos = new Set(fin.map(t => [t.u1, t.u2].filter(u => u && u !== '---').join(' + ')).filter(Boolean));
        const operarios = new Set();
        fin.forEach(t => [t.u1, t.u2].forEach(u => { if (u && u !== '---') operarios.add(u); }));

        return {
            fecha,
            qty, meta, mins,
            pct: meta > 0 ? (qty / meta) * 100 : 0,
            uph: mins > 0 ? (qty / mins) * 60 : 0,
            total: dd.length,
            finalizadas: fin.length,
            cumplio: ok,
            noCumplio: fin.length - ok - sinHora,
            sinHora,
            asignadas: asignadas.length,
            creadas: creadas.length,
            unidPend: [...asignadas, ...creadas].reduce((a, t) => a + (parseFloat(t.qty) || 0), 0),
            grupos: grupos.size,
            operarios: operarios.size
        };
    });
};

/** Promedio de rendimiento de cada grupo en el período, para comparar cada tarea contra su propia marca. */
const buildPromedioPorGrupo = (filas) => {
    const m = new Map();
    (filas || []).forEach(r => {
        if (r.mins <= 0) return;
        const c = m.get(r.grupo) || { suma: 0, n: 0 };
        c.suma += r.pct; c.n++;
        m.set(r.grupo, c);
    });
    const out = new Map();
    m.forEach((v, k) => out.set(k, v.n > 0 ? v.suma / v.n : 0));
    return out;
};

/** Fila de cierre de jornada en el reporte acumulado. */
const filaSubtotal = (fecha, tot) => {
    if (!tot) return '';
    const pct = tot.meta > 0 ? (tot.qty / tot.meta) * 100 : 0;
    const col = colorPorPct(pct);
    const uph = tot.mins > 0 ? (tot.qty / tot.mins) * 60 : 0;
    return `<tr style="background:rgba(245,158,11,0.07); border-bottom:2px solid rgba(245,158,11,0.25);">
        <td style="padding:0.6rem 1rem; color:#fbbf24; font-weight:900; font-size:0.72rem; text-transform:uppercase; letter-spacing:0.5px;">Total ${fecha.split('-').reverse().join('/')}</td>
        <td style="padding:0.6rem 1rem; color:rgba(255,255,255,0.5); font-size:0.72rem;">${tot.users.size} operario${tot.users.size !== 1 ? 's' : ''}</td>
        <td style="padding:0.6rem 1rem; text-align:center; color:rgba(255,255,255,0.5); font-weight:800; font-size:0.78rem;">${tot.tasks}</td>
        <td style="padding:0.6rem 1rem; text-align:center; color:#fbbf24; font-weight:900; font-size:0.95rem;">${tot.qty.toLocaleString('es-PE')}</td>
        <td style="padding:0.6rem 1rem; text-align:center; color:rgba(255,255,255,0.4); font-weight:800; font-size:0.8rem;">${Math.round(tot.meta).toLocaleString('es-PE')}</td>
        <td style="padding:0.6rem 1rem; text-align:center; color:${col}; font-weight:900; font-size:0.8rem;">${tot.qty - tot.meta >= 0 ? '+' : ''}${Math.round(tot.qty - tot.meta).toLocaleString('es-PE')}</td>
        <td style="padding:0.6rem 1rem; text-align:center; color:rgba(255,255,255,0.45); font-weight:800; font-size:0.78rem;">${fmtHM(tot.mins)}</td>
        <td style="padding:0.6rem 1rem; text-align:center; color:${col}; font-weight:900; font-size:0.85rem;">${Math.round(uph).toLocaleString('es-PE')}</td>
        <td style="padding:0.6rem 1.2rem; text-align:right; color:${col}; font-weight:900; font-size:0.75rem;">${Math.round(pct)}% de meta</td>
        <td style="padding:0.6rem 1rem;"></td>
    </tr>`;
};

/**
 * A qué día operativo pertenece este momento.
 *
 * La hora de corte era fija: las 06:00. Con un turno que sale 06:30 la última hora de la
 * jornada se registraba en el día siguiente, y había que pedir dos fechas para ver un solo
 * turno. Ahora sale de la hora de salida del turno noche, que se edita en
 * Configuración > Jornada de Trabajo y vale igual para todas las PC.
 */
const getLogicalDate = () => jornadaService.fechaLogicaDe();

/**
 * Los trabajadores indexados por DNI, para buscarlos dentro de un bucle sin pagar el precio
 * de getWorkers().
 *
 * getWorkers() COPIA el arreglo entero y lo REORDENA con localeCompare en cada llamada. Eso
 * está bien una vez para pintar una lista, pero llamarlo dentro de un forEach -o peor, dentro
 * del comparador de un sort, donde corre en cada comparación- multiplica ese costo por cada
 * fila. Medido con 60 trabajadores y 300 registros: 551 ms por fecha, contra 1 ms usando este
 * índice. Con un mes de historial eran 16 segundos de pantalla congelada.
 *
 * Se arma en el momento y no se guarda en ninguna variable de módulo: si se cacheara, un alta
 * o una baja de personal no se vería hasta recargar.
 */
const indiceWorkersPorDni = () => {
    const idx = new Map();
    (adminService.getWorkers() || []).forEach(w => {
        const dni = String(w.dni || w.Dni || '').trim();
        if (dni && !idx.has(dni)) idx.set(dni, w);
    });
    return idx;
};

/* ── BLOQUEO DE DÍAS CERRADOS ─────────────────────────────────────────────
   Antes se podía entrar en julio y editar una tarea de abril, y con eso se movían
   números ya presentados en comité. Ahora la jornada se cierra sola.
*/

/** El único que puede tocar una tarea de un día ya cerrado. */
const SUPERUSUARIO = 'dames';

const usuarioActual = () => {
    try { return String(JSON.parse(localStorage.getItem('logistics_session') || '{}').username || '').trim().toLowerCase(); }
    catch (e) { return ''; }
};

const esSuperusuario = () => usuarioActual() === SUPERUSUARIO;

/**
 * Una tarea queda cerrada cuando terminó su jornada y venció el margen de gracia. Antes se
 * trababa en el instante en que cambiaba la fecha lógica, así que una corrección de último
 * momento ya no entraba. Ahora el cierre y el margen se editan en Configuración > Jornada
 * de Trabajo. Desde ahí no se puede editar, reiniciar, borrar ni reasignar.
 * El superusuario no tiene este límite.
 */
const tareaCerrada = (t) => !!t && !!t.fecha && jornadaService.jornadaVencida(t.fecha) && !esSuperusuario();

/** El mismo aviso para todos los intentos, así la regla se explica una sola vez. */
const avisarCerrada = (t) => {
    const dia = String((t && t.fecha) || '').split('-').reverse().join('/');
    showPremiumAlert('JORNADA CERRADA',
        `La tarea del ${dia} ya no se puede modificar.\n\nLas tareas quedan abiertas ${jornadaService.textoCierre()}. Después solo ${SUPERUSUARIO.toUpperCase()} puede tocarlas.\n\nEs lo que evita que los números de días pasados cambien después de haberlos presentado.`,
        'warning');
};

/**
 * UNA TAREA NO TRABAJADA NO SE VUELVE A ABRIR.
 *
 * Cuando una corrida la cierra, su mercadería vuelve al buffer disponible y la ola nueva la
 * reclama en OTRA tarea. Reabrir la vieja pone dos tareas mandando por lo mismo: dos hojas,
 * dos operarios y el mismo stock contado dos veces.
 *
 * Lo pidió Daniel el 07-ago-2026, después de que su asistente viera una hoja vieja de la
 * Tarea47 —impresa por el defecto del radar— y le cambiara el estado creyendo que estaba
 * pendiente. La hoja mentía; la tarea llevaba rato cerrada.
 *
 * El superusuario queda exento, como en todo lo demás del módulo. Daniel lo probó primero
 * bloqueado para todos y decidió mantener la excepción: "dames tiene acceso a todo normal,
 * déjalo que yo pueda editar cualquier cosa. Todo lo demás deben ser bloqueados".
 *
 * El riesgo de reabrir una sigue existiendo —su mercadería ya está pedida en otra tarea—,
 * así que si alguna vez hay que deshacer algo, lo limpio es correr el proceso otra vez.
 */
const tareaNoTrabajada = (t) => !!t && t.status === 'Vencida' && !esSuperusuario();

const avisarNoTrabajada = (t) => {
    const n = String((t && t.id) || '').split('_').pop();
    showPremiumAlert('TAREA NO TRABAJADA',
        `La ${n} se cerró en una corrida porque no se alcanzó a trabajar.\n\nSu mercadería ya está pedida en una tarea NUEVA, así que esta no se puede reabrir: serían dos hojas mandando por lo mismo.\n\nBusque el código en la lista de tareas de hoy; está en alguna de las nuevas.`,
        'warning');
};

/**
 * LA TAREA COMO ESTÁ AHORA EN LA LISTA, NO COMO ESTABA AL ABRIR EL MODAL.
 *
 * EL DEFECTO QUE ESTO VIENE A CERRAR (Daniel, 10-ago-2026): "justo cuando estoy asignando y
 * el ícono se pone amarillo, no me asigna la tarea. Pongo asignar, pongo los usuarios, y no
 * queda". No era el servidor ni la red.
 *
 * El radar recarga la lista cada 20 segundos y lo hace REEMPLAZANDO `almacenajeTasksCache`
 * por objetos nuevos traídos del servidor. Los modales, en cambio, guardan la tarea que
 * encontraron AL ABRIRSE. Elegir dos operarios lleva más de 20 segundos, así que el radar
 * pasa en el medio y esa referencia deja de pertenecer a la lista: queda una ficha suelta.
 * Lo que se escriba encima no lo ve nadie —el redibujado sale de la lista, no de la ficha—,
 * y la tarea aparece otra vez sin asignar.
 *
 * Por eso, antes de tocar una tarea, se vuelve a pedir por su id. Hay que llamarla al
 * PRINCIPIO del handler, antes de escribir nada: si se llamara al final, los cambios ya
 * estarían hechos sobre la ficha vieja y se perderían igual.
 *
 * Devuelve null si la tarea ya no está —la borraron desde otra PC—, y entonces hay que
 * avisar en vez de escribir sobre algo que no existe.
 */
const tareaDelCache = (t) => {
    const id = t && t.id;
    if (!id) return null;
    return almacenajeTasksCache.find(x => x && x.id === id) || null;
};

/** Avisa cuando la tarea se esfumó de la lista mientras el modal estaba abierto. */
const avisarTareaDesaparecida = (t, accion) => {
    const n = String((t && t.id) || '').split('_').pop();
    showPremiumAlert('LA TAREA YA NO ESTÁ',
        `No se pudo ${accion} la ${n}: desapareció de la lista mientras esta ventana estaba abierta.\n\nSeguramente la borraron o se corrió el proceso desde otra PC. Cierre esta ventana y vuelva a mirar la lista.`,
        'error');
};

/**
 * NO REPINTAR LA PANTALLA POR DEBAJO DE UNA VENTANA ABIERTA.
 *
 * El radar redibuja la lista cada 20 segundos. Si hay un modal encima —asignar, finalizar,
 * editar—, ese redibujado no aporta nada (la ventana tapa la tabla) y sí molesta: mueve el
 * scroll y reemplaza las tareas justo mientras alguien está trabajando sobre una.
 *
 * Los datos igual quedan al día en memoria; lo único que se posterga es el dibujo, y se
 * hace solo al cerrar la ventana, que es cuando la tabla se vuelve a ver.
 */
const hayModalDeTareaAbierto = () => !!document.querySelector(
    '#assign_task_modal, #partial_avance_modal, #edit_task_modal, #wmsAuditModal, #modal_fecha_operativa'
);

/**
 * Semana laboral (lunes a sábado) a la que pertenece la fecha lógica. El domingo no se
 * trabaja, así que se considera parte de la semana que acaba de cerrar: si abres la web
 * un domingo, ves el lunes-sábado anterior, no una semana vacía que recién empieza.
 */
const getSemanaLaboral = () => {
    // Mediodía: evita que el cambio de horario mueva el día al restar fechas
    const base = new Date(getLogicalDate() + 'T12:00:00');
    const diasDesdeLunes = (base.getDay() + 6) % 7;   // getDay(): 0=domingo, 1=lunes...
    const lunes = new Date(base);
    lunes.setDate(base.getDate() - diasDesdeLunes);
    const sabado = new Date(lunes);
    sabado.setDate(lunes.getDate() + 5);
    const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    return { desde: fmt(lunes), hasta: fmt(sabado) };
};

/**
 * La fecha lógica corrida N días hacia atrás. Se ancla al mediodía para que un cambio de
 * horario no mueva el día al restar.
 */
const fechaLogicaMenos = (dias) => {
    const d = new Date(getLogicalDate() + 'T12:00:00');
    d.setDate(d.getDate() - dias);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

// --- PERSISTENCIA TAREAS ALMACENAJE ---
let almacenajeTaskMode = localStorage.getItem('almacenajeTaskMode') || 'resumen';
let selectedTaskDate = null; // Filtro de fecha seleccionado
if (!window.__almacenajeStartDate) window.__almacenajeStartDate = getLogicalDate();
if (!window.__almacenajeEndDate) window.__almacenajeEndDate = getLogicalDate();
// Corregir datos vive en Config. Tareas y lleva su propio rango: se corrige un tramo del
// histórico, que no tiene por qué ser el que se esté mirando en Tareas Día.
if (!window.__correccionDesde) window.__correccionDesde = getLogicalDate();
if (!window.__correccionHasta) window.__correccionHasta = getLogicalDate();
// La pantalla de prueba de la sugerencia lleva su propio rango
if (!window.__sugStart) window.__sugStart = getLogicalDate();
if (!window.__sugEnd) window.__sugEnd = getLogicalDate();
// El panel de KPI abre con la semana laboral completa (lunes a sábado), no con un solo día
const _semanaKpi = getSemanaLaboral();
if (!window.__kpiStartDate) window.__kpiStartDate = _semanaKpi.desde;
if (!window.__kpiEndDate) window.__kpiEndDate = _semanaKpi.hasta;
// Los dos reportes de abajo (Marcas y Gender RIMS) llevan su propio rango, aparte del
// panel de KPI. Como viven en window, al abrir la web arrancan siempre en el día actual.
if (!window.__repMarcasStart) window.__repMarcasStart = getLogicalDate();
if (!window.__repMarcasEnd) window.__repMarcasEnd = getLogicalDate();
if (!window.__repGenderStart) window.__repGenderStart = getLogicalDate();
if (!window.__repGenderEnd) window.__repGenderEnd = getLogicalDate();
/**
 * EL COMODÍN DE LA TALLA ES UNO SOLO: 'S/T'.
 *
 * Convivían dos —'S/T' en el cálculo del papel y 'S/TALLA' en el generador de tareas— y como
 * la talla es la CLAVE con la que se cruzan las dos mitades, un artículo sin talla numérica
 * nunca se encontraba consigo mismo: la hoja salía con todo al piso, la reserva en cero y el
 * destino en guion, sin ningún aviso.
 *
 * Se sigue aceptando 'S/TALLA' al leer porque las tareas ya guardadas lo tienen escrito así,
 * y esas hojas se reimprimen. Al escribir, siempre 'S/T'.
 */
const normalizarTalla = (t) => {
  const s = String(t == null ? '' : t).trim().toUpperCase();
  if (!s || s === 'S/TALLA' || s === 'S/T' || s === 'SIN TALLA') return 'S/T';
  return s;
};

let expandedWeeks = []; // Semanas expandidas en el historial
let almacenajeTasksCache = [];
try {
    const stored = localStorage.getItem('logistics_sync_v24_almacenaje_tasks');
    if (stored) almacenajeTasksCache = JSON.parse(stored);
} catch(e) { almacenajeTasksCache = []; }
if (!Array.isArray(almacenajeTasksCache)) almacenajeTasksCache = [];

// [MIGRACIÓN DE IDENTIFICADORES] Migrar tareas antiguas sin prefijo de fecha a formato único
let migratedInit = false;
almacenajeTasksCache = almacenajeTasksCache.map(t => {
    if (t && t.status === 'Auditado') { t.status = 'Finalizado'; t.audited = true; }
    if (t && t.id && !t.id.includes('_')) {
        t.id = `${t.fecha}_${t.id}`;
        migratedInit = true;
    }
    return t;
});
const safeSaveAlmacenajeTasksCache = () => {
    try {
        localStorage.setItem('logistics_sync_v24_almacenaje_tasks', JSON.stringify(almacenajeTasksCache));
    } catch (e) {
        if (e.name === 'QuotaExceededError' || e.code === 22 || e.name === 'NS_ERROR_DOM_QUOTA_REACHED') {
            console.warn("🧹 [PULSE] LocalStorage lleno. Auto-purgando tareas antiguas...");
            const doceHoras = 12 * 60 * 60 * 1000;
            const now = Date.now();
            almacenajeTasksCache = almacenajeTasksCache.filter(t => {
                if (t.status === 'Finalizada' && t.termino) {
                    const ts = new Date(t.termino).getTime();
                    if (!isNaN(ts) && (now - ts > doceHoras)) return false;
                }
                return true;
            });
            try {
                localStorage.setItem('logistics_sync_v24_almacenaje_tasks', JSON.stringify(almacenajeTasksCache));
            } catch (err2) {
                console.error("❌ [PULSE] Fallo crítico de cuota incluso tras purga.");
            }
        }
    }
};

if (migratedInit) {
    safeSaveAlmacenajeTasksCache();
}

// --- PERSISTENCIA AVANZADA (IndexedDB vía csvHub) ---
const updateSyncIndicator = (status, text) => {
  const el = document.getElementById('sync-indicator');
  const icon = document.getElementById('sync-icon');
  const txt = document.getElementById('sync-text');
  if (!el) return;
  el.className = `sync-${status}`;
  if (icon) icon.innerText = status === 'online' ? '✅' : (status === 'working' ? '⏳' : '❌');
  if (txt) txt.innerText = text;
};

const saveAlmacenajeTasks = async (partialTask = null) => {
  try {
      updateSyncIndicator('working', 'GUARDANDO EN LA NUBE...');
      
      // 1. Persistencia LOCAL inmediata
      safeSaveAlmacenajeTasksCache();
      adminService.adminStore.almacenaje_tasks = almacenajeTasksCache;
      // Activar guard de pull inmediatamente para proteger el estado local durante el debounce
      if (window._pulseSyncState && window._pulseSyncState.lastPushTimes) {
          window._pulseSyncState.lastPushTimes['almacenaje_tasks'] = Date.now();
      }

        // Cuando cambia UNA tarea se manda solo esa: el servidor la reemplaza por id y deja
        // el resto como está. Antes se subía siempre el array entero, así que la última PC en
        // guardar pisaba a todas las demás: finalizabas una tarea, el asistente asignaba otra
        // desde su PC, y su copia -que todavía tenía la tuya en Asignado- revertía tu cambio.
        // El array completo se sigue mandando cuando de verdad cambia el conjunto: al procesar
        // tareas nuevas, al borrarlas o al limpiar la jornada.
        const dataToSave = partialTask || almacenajeTasksCache;
        console.log(partialTask
            ? `📡 [PULSE] Sincronización: enviando SOLO la tarea ${partialTask.id}.`
            : `📡 [PULSE] Sincronización: Enviando ${almacenajeTasksCache.length} tareas (COMPLETO) a la nube.`);

        const success = await adminService.saveAlmacenajeTasks(dataToSave);
        
        if (success) {
            if (partialTask) {
                delete partialTask._dirty;
            } else {
                almacenajeTasksCache.forEach(t => delete t._dirty);
            }
            safeSaveAlmacenajeTasksCache();
            updateSyncIndicator('online', 'NUBE ACTUALIZADA ✅');
            setTimeout(() => updateSyncIndicator('online', `SISTEMA v${VERSION} ONLINE`), 3000);
        } else {
            console.warn("⚠️ [SYNC] Error de sincronización. Los datos permanecen seguros en tu PC.");
            updateSyncIndicator('offline', 'PENDIENTE DE SINCRONIZACIÓN');
        }
        // DEVUELVE SI LLEGÓ. Antes no devolvía nada, así que quien la llamaba no podía saber
        // si el guardado había funcionado — y todos la llamaban sin esperarla. El 07-ago-2026
        // la Tarea64 quedó con el avance guardado y el estado en Asignado: el modal cerró, dijo
        // "TAREA FINALIZADA" y redibujó, mientras el guardado se perdía en silencio.
        return !!success;
    } catch (e) {
        console.error("[SYNC] Error crítico:", e);
        updateSyncIndicator('offline', 'FALLO CRÍTICO DE CONEXIÓN');
        return false;
    }
};

/**
 * Reescribe el bloque completo de tareas, pero releyendo primero lo que hay en el servidor.
 *
 * Procesar, auditar y borrar son las operaciones que no pueden mandarse de a una tarea:
 * cambian el conjunto. Si subieran lo que esta PC tiene en memoria, pisarían todo lo que
 * otra PC hizo desde que se abrió la pantalla — las asignaciones del asistente, por ejemplo.
 * Releyendo justo antes de escribir, la ventana de riesgo pasa de las horas que lleve la
 * pantalla abierta a los milisegundos entre la lectura y la escritura.
 *
 * Si el servidor no responde se sigue con lo local: es preferible guardar con el riesgo
 * viejo a perder la operación que el usuario acaba de hacer.
 *
 * @param transformar recibe las tareas del servidor y devuelve cómo tienen que quedar.
 */
/**
 * UNA TAREA CREADA VIVE 48 HORAS.
 *
 * Hasta acá una tarea que nadie trabajaba se quedaba abierta para siempre, y como el descuento
 * de lo comprometido solo miraba las tareas del MISMO día, cada noche nacía una tarea nueva por
 * el mismo stock. Medido el 06-ago-2026: de 502 artículos con tarea abierta, 180 la tenían en
 * más de un día, y eso sumaba 470.600 unidades fantasma. La más vieja era del 25 de mayo.
 *
 * Ese número inflado es el que hacía que el reporte de buffer marcara 57% cuando el trabajo
 * real había sido 81%.
 *
 * Regla de Daniel, 06-ago-2026: "no tiene que haber ninguna creada; se puede vencer la tarea
 * después de cuarenta y ocho horas". El sistema la caduca solo, sin que nadie tenga que
 * acordarse.
 */
const HORAS_VENCIMIENTO = 48;

/**
 * Cuántas horas lleva la tarea. Se mide desde que se procesó; si esa marca falta —las tareas
 * viejas no siempre la traen— se cae a su fecha operativa a las 19:00, que es cuando corre la
 * ola. Sin eso, una tarea sin `fechaProcesado` no vencería nunca.
 */
const horasDeTarea = (t) => {
    const ts = t && t.fechaProcesado ? new Date(t.fechaProcesado).getTime() : NaN;
    if (!isNaN(ts)) return (Date.now() - ts) / 3600000;
    const d = t && t.fecha ? new Date(`${t.fecha}T19:00:00`) : null;
    return (d && !isNaN(d.getTime())) ? (Date.now() - d.getTime()) / 3600000 : Infinity;
};

/**
 * Si su mercadería sigue comprometida.
 *
 * LAS 48 HORAS VALEN PARA TODAS, NO SOLO PARA LAS CREADAS. Antes una Asignada no caducaba
 * nunca —"alguien la empezó y su hoja está en la calle"—, y ese razonamiento vale para unas
 * horas, no para meses: el 06-ago-2026 había 13 tareas en Asignado sin cerrar, cinco de
 * ellas del 25 de MAYO, reteniendo 4.443 pares que no podían entrar en ninguna corrida.
 * Si a las 48 horas nadie la cerró, no se está trabajando.
 */
const esTareaViva = (t) => {
    if (!t || t.status === 'Finalizado' || t.status === 'Vencida') return false;
    return horasDeTarea(t) < HORAS_VENCIMIENTO;
};

/**
 * CIERRA LO QUE NO SE TRABAJÓ, AL PROCESAR. Devuelve cuántas se cerraron.
 *
 * En pantalla estas tareas dicen NO TRABAJADA, que es exactamente lo que pasó: nadie las
 * tocó durante el turno. Por dentro siguen marcadas 'Vencida' para no tener que reescribir
 * las 357 que ya existían ni la docena de sitios que comparan contra ese valor.
 *
 * No es un error ni una excepción: un turno que cierra con quince NO TRABAJADA es un turno
 * normal. La ola siguiente las vuelve a proponer si su mercadería sigue en el buffer, con
 * la cantidad que diga el stock de ese momento.
 *
 * Solo toca las CREADA. Una Asignada está en manos de alguien y se respeta.
 */
const cerrarCreadasSinTrabajar = (tareas) => {
    let n = 0;
    (tareas || []).forEach(t => {
        if (t && t.status === 'Creada') {
            t.status = 'Vencida';
            t.vencidaEl = selloLocalTarea();
            // Se distingue de la que caducó sola por las 48 horas: esta la cerró una corrida.
            t.cerradaPorCorrida = true;
            n++;
        }
    });
    return n;
};

/**
 * CÓMO SE LLAMA CADA ESTADO EN PANTALLA.
 *
 * 'Vencida' se muestra como NO TRABAJADA. Adentro el valor no cambia —hay 357 tareas ya
 * guardadas así y una docena de sitios que comparan contra él—, pero la palabra que ve la
 * gente sí: "vencida" suena a error, y no lo es. Es el final normal de lo que no se alcanzó
 * en el turno. Decisión de Daniel, 07-ago-2026.
 *
 * Y no puede llamarse "Cerrada": quedaría al lado de FINALIZADO en la misma columna y las
 * dos se leerían como "ya está lista", cuando significan lo contrario.
 */
const ROTULOS_ESTADO = { 'Vencida': 'NO TRABAJADA' };
const rotuloEstado = (t) => {
    const s = String((t && t.status) || '');
    return ROTULOS_ESTADO[s] || s.toUpperCase();
};

/** El color de cada estado. NO TRABAJADA va en gris: no se hizo, pero no es una falla. */
const colorEstado = (t) => {
    const s = String((t && t.status) || '');
    if (s === 'Finalizado') return '#22c55e';
    if (s === 'Asignado') return '#eab308';
    if (s === 'Vencida') return '#94a3b8';
    return 'var(--text-muted)';
};

/** Pasa a Vencida toda tarea sin cerrar que cruzó las 48 horas. Devuelve cuántas cambiaron. */
const vencerTareasViejas = (tareas) => {
    let n = 0;
    (tareas || []).forEach(t => {
        if (t && t.status !== 'Finalizado' && t.status !== 'Vencida'
            && horasDeTarea(t) >= HORAS_VENCIMIENTO) {
            t.status = 'Vencida';
            // Queda el sello de cuándo se venció: sirve para saber que caducó sola y no que
            // alguien la cerró a mano.
            t.vencidaEl = selloLocalTarea();
            n++;
        }
    });
    return n;
};

/**
 * Dos tareas vivas no pueden llamarse igual. Devuelve cuántas se renumeraron.
 *
 * La numeración reiniciaba cada día, así que el 06-ago-2026 había tres tareas distintas
 * llamadas "Tarea2": una del 4, otra del 5 y otra del 6. Mientras cada día se miraba por
 * separado no molestaba, pero desde que el papel saca todas las Creadas juntas el
 * asistente termina con tres hojas que dicen lo mismo y no sabe cuál es cuál.
 *
 * EL NÚMERO SE LO QUEDA LA TAREA DE HOY, y si ninguna es de hoy, la más antigua. Las
 * demás se mueven al primer número libre por encima del más alto en uso: renumerar la de
 * hoy sería peor que el problema, porque es de la que se habla en el turno y la que el
 * asistente ya tiene delante.
 *
 * Solo mira las vivas. Una finalizada puede repetir número con una de hoy sin molestar a
 * nadie, y arrastrar el historial entero haría que en un mes anduviéramos por la Tarea900.
 */
/**
 * El orden en que salen las tareas del papel: por NÚMERO, de menor a mayor.
 *
 * Sin esto salían en el orden en que estaban guardadas —la 47, después la 49, y la 36 al
 * final—, que no es ningún orden para quien reparte las hojas. Se ordena por número y no
 * por fecha porque el número es lo que se lee en el papel y por lo que se pregunta en el
 * turno; con la renumeración, dos tareas vivas nunca comparten número.
 */
const ordenParaElPapel = (a, b) => {
    const num = (t) => {
        const id = String((t && (t.id || (t.tarea && t.tarea.id))) || '');
        const c = id.includes('_') ? id.split('_')[1] : id;
        const n = parseInt(String(c).replace('Tarea', ''));
        return isNaN(n) ? Number.MAX_SAFE_INTEGER : n;
    };
    const fecha = (t) => String((t && (t.fecha || (t.tarea && t.tarea.fecha))) || '');
    return num(a) - num(b) || fecha(a).localeCompare(fecha(b));
};

const desempatarNumeros = (tareas) => {
    const todas = (tareas || []).filter(t => t && t.id);
    const numeroDe = (t) => {
        const c = String(t.id).includes('_') ? String(t.id).split('_')[1] : String(t.id);
        const n = parseInt(String(c).replace('Tarea', ''));
        return isNaN(n) ? null : n;
    };

    /**
     * EL NÚMERO LIBRE SE BUSCA ENTRE TODAS LAS DE ESE DÍA, NO SOLO ENTRE LAS VIVAS.
     *
     * Acá estaba el error que le llenó la pantalla de tareas repetidas al Daniel el
     * 06-ago-2026. El número libre salía de `Math.max(...)` sobre las VIVAS, con el
     * razonamiento de que "una finalizada puede repetir número sin molestar a nadie". Es
     * falso: el id es `fecha_TareaN` y ES LA CLAVE con la que el servidor reemplaza cada
     * tarea. Del 05/08 el mayor número vivo era 46, así que repartió 47, 48, 49, 50, 51 y
     * 52 — que ya los usaban seis tareas finalizadas de ese mismo día. Resultado: seis
     * pares de tareas distintas compartiendo id, dos hojas iguales para el asistente, y
     * el avance de dos de ellas contado dos veces (4.664 pares que nadie hizo).
     *
     * Además el contador era uno solo para todas las fechas, cuando el id se arma por
     * fecha. Ahora cada día lleva su propia cuenta y se arranca por encima de su máximo,
     * mirando finalizadas y vencidas incluidas.
     *
     * Que dos PC lo calculen a la vez ya no rompe nada: partiendo del mismo máximo por
     * fecha, las dos llegan al mismo número para la misma tarea.
     */
    const usadosPorFecha = new Map();
    todas.forEach(t => {
        const n = numeroDe(t);
        if (n === null) return;
        const f = String(t.fecha || '');
        if (!usadosPorFecha.has(f)) usadosPorFecha.set(f, new Set());
        usadosPorFecha.get(f).add(n);
    });

    const porNumero = new Map();
    todas.filter(esTareaViva).forEach(t => {
        const n = numeroDe(t);
        if (n === null) return;
        if (!porNumero.has(n)) porNumero.set(n, []);
        porNumero.get(n).push(t);
    });

    const hoy = getLogicalDate();
    let cambiadas = 0;
    [...porNumero.keys()].sort((a, b) => a - b).forEach(n => {
        const grupo = porNumero.get(n);
        if (grupo.length < 2) return;
        // Primero la de hoy; entre las demás, la más antigua
        grupo.sort((a, b) => (String(a.fecha) === hoy ? 0 : 1) - (String(b.fecha) === hoy ? 0 : 1)
                          || String(a.fecha).localeCompare(String(b.fecha)));
        grupo.slice(1).forEach(t => {
            const f = String(t.fecha || '');
            const usados = usadosPorFecha.get(f) || new Set();
            let libre = Math.max(0, ...usados) + 1;
            while (usados.has(libre)) libre++;
            usados.add(libre);
            usadosPorFecha.set(f, usados);
            t.id = `${f}_Tarea${libre}`;
            cambiadas++;
        });
    });
    return cambiadas;
};

/**
 * LA TAREA VIVA SE CORRIGE CON EL STOCK DE ESTA NOCHE. LA PASADA NO SE TOCA.
 *
 * Ejemplo de Daniel: el 15 llegan 1.000 pares y nace la Tarea1. El 16 picking se llevó 30, así
 * que en el buffer hay 970. Hoy nacería OTRA tarea con 970 y la del 15 quedaría viva con 1.000
 * —el sistema creería que hay 1.970 por almacenar—. Ahora sigue siendo la Tarea1, con su fecha
 * original, y la hoja dice 970.
 *
 * Solo se tocan las Creada que siguen vivas. Una Asignada tiene su hoja en la calle y una
 * Vencida o Finalizada es historia: esas quedan como quedaron.
 *
 * Si a la tarea no le queda nada —picking se llevó todo— se vence ahí mismo: no hay nada que
 * almacenar y dejarla abierta volvería a bloquear stock que ya no existe.
 */
const ajustarTareasVivas = (tareas, filasStock) => {
    const hoy = new Map();
    (filasStock || []).forEach(row => {
        const raw = Array.isArray(row) ? row : Object.values(row);
        const ubi = String(row['Ubicación actual'] || row['Ubicacion'] || row['Ubicación'] || '').trim().toUpperCase();
        if (!ubi.startsWith('CDBUFFER') || ubi.startsWith('CDBUFFER-C')) return;
        const k = `${String(raw[1] || '').trim()}|${ubi}`;
        const q = parseFloat(String(row['Cantidad actual'] || row['Cantidad'] || 0).replace(/,/g, '')) || 0;
        hoy.set(k, (hoy.get(k) || 0) + q);
    });

    let cambiadas = 0, vencidasVacias = 0;
    (tareas || []).forEach(t => {
        if (!t || t.status !== 'Creada' || !esTareaViva(t)) return;
        let toco = false, totalTarea = 0;
        (t.items || []).forEach(art => {
            let bq = 0;
            (art.items || []).forEach(i => {
                const ubi = String(i.ubi || '').trim().toUpperCase();
                if (!ubi.startsWith('CDBUFFER')) return;   // las de zona son referencia, no trabajo
                const q = hoy.get(`${String(i.skuFull || '').trim()}|${ubi}`) || 0;
                if (q !== i.qty) { i.qty = q; toco = true; }
                bq += q;
            });
            if (art.bufferQty !== bq) { art.bufferQty = bq; toco = true; }
            totalTarea += bq;
        });
        if (!toco) return;
        t.qty = totalTarea;
        cambiadas++;
        if (totalTarea <= 0) { t.status = 'Vencida'; t.vencidaEl = selloLocalTarea(); vencidasVacias++; }
    });
    return { cambiadas, vencidasVacias };
};

/**
 * DESDE CUÁNDO ESPERA CADA ARTÍCULO.
 *
 * Cuando un artículo vuelve a generar tarea porque la anterior caducó, la nueva hereda la fecha
 * en que empezó a esperar, no la de hoy. Sin eso la deuda es invisible: hay códigos en el
 * buffer desde el 22 de junio y en la lista se ven igual que uno que llegó anoche.
 */
const esperaPorArticulo = (tareas, desdeCero = false) => {
    // ALMACENARLO SALDA LA ESPERA.
    //
    // Acá se miraba la tarea abierta más vieja y nada más, y eso daba números imposibles. El
    // 8816458 salió con "esperando hace 44 días" —lo cazó Daniel— cuando en realidad se había
    // almacenado el 1, el 4 y el 5 de agosto: los 44 días venían de tres tareas Creada de junio
    // y julio que nunca se trabajaron y cuya mercadería hace rato no existe.
    //
    // Una tarea vieja sin cerrar no prueba que el artículo esté esperando desde entonces. Lo
    // que sí lo prueba es que NO se haya almacenado en el medio. Así que las esperas anteriores
    // a la última vez que se finalizó una tarea suya se descartan: esa deuda ya se pagó.
    const ultimaFinalizada = new Map();
    (tareas || []).forEach(t => {
        if (!t || t.status !== 'Finalizado' || !t.fecha) return;
        (t.items || []).forEach(a => {
            if (!a || !a.sku7) return;
            const prev = ultimaFinalizada.get(a.sku7);
            if (!prev || t.fecha > prev) ultimaFinalizada.set(a.sku7, t.fecha);
        });
    });

    const m = new Map();
    (tareas || []).forEach(t => {
        if (!t || t.status === 'Finalizado') return;
        // Con `desdeCero` se ignora el esperaDesde ya grabado y se recalcula desde las fechas
        // de las tareas. Hace falta para arreglar las que quedaron con un valor viejo: si se
        // leyera el grabado, un dato equivocado se copiaría a sí mismo para siempre.
        const f = desdeCero ? t.fecha : (t.esperaDesde || t.fecha);
        if (!f) return;
        (t.items || []).forEach(a => {
            if (!a || !a.sku7) return;
            const fin = ultimaFinalizada.get(a.sku7);
            if (fin && String(f) <= String(fin)) return;   // se almacenó después: ya no cuenta
            const prev = m.get(a.sku7);
            if (!prev || f < prev) m.set(a.sku7, f);
        });
    });
    return m;
};

/**
 * REFRESCA LA ANTIGÜEDAD DE LAS TAREAS VIVAS.
 *
 * El `esperaDesde` viaja grabado en la tarea, así que una tarea que ya existe se queda con el
 * valor que le tocó el día que nació. Cuando se corrigió la cuenta —almacenar el artículo salda
 * su espera— las tareas de antes siguieron mostrando lo viejo: la Tarea60 seguía diciendo
 * "esperando hace 44 días" después del arreglo, porque nadie le tocaba el dato.
 *
 * Se recalcula desde cero a propósito. Leyendo el grabado, un valor equivocado se copiaría a sí
 * mismo en cada corrida y no habría forma de enderezarlo.
 */
const refrescarEspera = (tareas) => {
    const base = esperaPorArticulo(tareas, true);
    let n = 0;
    (tareas || []).forEach(t => {
        if (!t || t.status === 'Finalizado' || t.status === 'Vencida') return;
        const fechas = (t.items || []).map(a => base.get(a && a.sku7)).filter(Boolean).sort();
        const nueva = fechas[0] || t.fecha;
        if (t.esperaDesde !== nueva) { t.esperaDesde = nueva; n++; }
    });
    return n;
};

/** La hora de acá, no la de Greenwich. Mismo criterio que la ficha del Maestro (v29.0080). */
const selloLocalTarea = () => {
    const d = new Date(), dd = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${dd(d.getMonth() + 1)}-${dd(d.getDate())} `
         + `${dd(d.getHours())}:${dd(d.getMinutes())}:${dd(d.getSeconds())}`;
};

/** 'YYYY-MM-DD' de una fecha, en hora de acá. */
const soloElDia = (d) => {
    const dd = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${dd(d.getMonth() + 1)}-${dd(d.getDate())}`;
};

/**
 * LA HORA EN QUE PASA ALGO, EN HORA DE ACÁ. NUNCA `toISOString()`.
 *
 * Los botones de asignar y finalizar estampaban `new Date().toISOString()`, que devuelve
 * UTC — cinco horas adelante. Asignar a las 20:44 quedaba grabado como `01:44Z` del día
 * SIGUIENTE, así que el trabajo del turno noche se le imputaba al día equivocado desde el
 * primer clic. Es la misma trampa que ya está anotada para las fechas de la plataforma, y
 * sobrevivió acá porque estos tres estampados no se habían revisado.
 *
 * Mismo formato que escribe la ventana de horas (`YYYY-MM-DDTHH:MM:SS`, sin Z), así que
 * las dos vías guardan igual y nada tiene que adivinar cuál es cuál.
 */
const selloHoraLocal = () => {
    const d = new Date(), dd = (n) => String(n).padStart(2, '0');
    return `${soloElDia(d)}T${dd(d.getHours())}:${dd(d.getMinutes())}:${dd(d.getSeconds())}`;
};

/**
 * QUÉ DÍA TIENE YA REGISTRADA LA TAREA, si es que tiene alguno.
 *
 * Las horas de una tarea viajan en DOS formatos y hay que saberlo para leerlas: las que se
 * escriben a mano quedan en hora de acá (`2026-08-05T11:30:00`) y las que pone el sistema al
 * tocar un botón salen de `toISOString()`, o sea en UTC y con Z (`2026-08-07T01:38:47.104Z`),
 * cinco horas adelante. Leer una UTC como si fuera local corre el trabajo casi medio día.
 */
const diaYaRegistrado = (t) => {
    const s = String((t && t.inicio) || '').trim();
    if (!s) return null;
    if (s.endsWith('Z')) {
        const d = new Date(s);
        return isNaN(d.getTime()) ? null : soloElDia(d);
    }
    return /^\d{4}-\d{2}-\d{2}/.test(s) ? s.slice(0, 10) : null;
};

/** El día siguiente de 'YYYY-MM-DD'. Para el turno que cruza la medianoche. */
const sumarUnDia = (fechaStr) => {
    const d = new Date(`${fechaStr}T12:00:00`);   // mediodía: el horario de verano no mueve el día
    if (isNaN(d.getTime())) return fechaStr;
    d.setDate(d.getDate() + 1);
    return soloElDia(d);
};

/** El día anterior de 'YYYY-MM-DD'. */
const restarUnDia = (fechaStr) => {
    const d = new Date(`${fechaStr}T12:00:00`);
    if (isNaN(d.getTime())) return fechaStr;
    d.setDate(d.getDate() - 1);
    return soloElDia(d);
};

/**
 * A QUÉ JORNADA PERTENECEN LAS HORAS QUE YA TIENE LA TAREA.
 *
 * `diaYaRegistrado` devuelve el día del CALENDARIO; esto devuelve el de la JORNADA, que es
 * lo que hay que comparar cuando se reescribe una hora. Sin esta distinción, corregir la
 * hora de una tarea de madrugada la corría otro día más en cada guardado.
 */
const jornadaYaRegistrada = (t) => {
    const s = String((t && t.inicio) || '').trim();
    if (!s) return null;
    const d = new Date(s.endsWith('Z') ? s : s.replace(' ', 'T'));
    return isNaN(d.getTime()) ? null : jornadaService.fechaLogicaDe(d);
};

/**
 * QUÉ DÍA DEL CALENDARIO LE CORRESPONDE A UNA HORA ESCRITA A MANO.
 *
 * La fecha sale de LA HORA, no del momento en que alguien la escribe. Son dos cosas
 * distintas y confundirlas movía el trabajo de día:
 *
 *  · La madrugada de una jornada ya es el día siguiente del calendario. La noche del
 *    viernes que sigue a las 02:00 es sábado 02:00, no viernes 02:00. Guardarla como
 *    viernes dejaba la tarea "empezada antes de nacer" — hay 2.372 así.
 *
 *  · Y una hora escrita NUNCA puede caer en el futuro. El 08-ago-2026 alguien anotó por
 *    la mañana un trabajo de las 23:30 de la noche anterior: como a esa hora la jornada
 *    de hoy ya había abierto, quedó sellado 08/08 23:30 —esta noche, que todavía no pasa—
 *    y sus 215 unidades aparecieron en el sábado. Eran del viernes.
 */
const diaDelSello = (jornada, hora) => {
    let dia = (hora < jornadaService.horarioDe(jornada).nocheSalida) ? sumarUnDia(jornada) : jornada;
    if (new Date(`${dia}T${hora}:00`).getTime() > Date.now()) dia = restarUnDia(dia);
    return dia;
};

/**
 * DOS TAREAS NO PUEDEN COMPARTIR ID. Devuelve la lista sin repetidos; gana la última.
 *
 * El 07-ago-2026, después del corte de Daniel, el servidor terminó con 40 tareas vivas que
 * eran 25 de verdad: 15 estaban guardadas DOS VECES, con el mismo id. El reporte las contaba
 * dos veces —39.300 pares donde el buffer tenía 25.888— y el papel habría salido con 15 hojas
 * repetidas, mandando a dos operarios al mismo sitio.
 *
 * El id no es una etiqueta: es la clave con la que el servidor reemplaza cada tarea por PATCH
 * y con la que la pantalla las une al refrescar. Con dos registros iguales, cuál gana depende
 * del orden del array, que no es de nadie.
 *
 * Se limpia acá, en el embudo por el que pasan TODAS las reescrituras del bloque, y no en
 * cada sitio que llama: así ninguna vía futura puede volver a meter un duplicado. Gana el
 * último porque las transformaciones agregan al final: si algo se append-eó dos veces, la
 * segunda copia es la buena.
 */
const sinIdsRepetidos = (tareas) => {
    const porId = new Map();
    let repetidas = 0;
    (tareas || []).forEach(t => {
        if (!t || !t.id) return;
        if (porId.has(t.id)) repetidas++;
        porId.set(t.id, t);
    });
    if (repetidas) console.warn(`[Almacenaje] se descartaron ${repetidas} tarea(s) con id repetido antes de guardar.`);
    return [...porId.values()];
};

const guardarBloqueFusionado = async (transformar) => {
    let base = almacenajeTasksCache;
    try {
        const frescas = await adminService.traerTareasFrescas();
        if (Array.isArray(frescas)) base = frescas;
    } catch (e) {
        console.warn('[PULSE] No se pudo releer del servidor; se guarda con lo de esta PC:', e && e.message);
    }
    almacenajeTasksCache = sinIdsRepetidos(transformar(base) || []);
    await saveAlmacenajeTasks();
};

const loadAlmacenajeTasks = async () => {
  try {
      updateSyncIndicator('working', 'SINCRONIZANDO CON LA NUBE...');
      // Carga desde el puente v24 (que ya hizo el pull)
      const syncedTasks = await adminService.loadAlmacenajeTasks();
        if (typeof adminService.loadAlmacenajeTasksHistory === 'function') {
            await adminService.loadAlmacenajeTasksHistory();
        }
      if (Array.isArray(syncedTasks)) {
          // [SINCRONIZACIÓN TOTAL] Ahora permite que la nube limpie los datos locales si se borraron allá.
          if (Array.isArray(syncedTasks)) {
              almacenajeTasksCache = syncedTasks.map(newTask => {
                  const cleanTaskId = (id) => id.includes('_') ? id.split('_')[1] : id;
                  const localTask = almacenajeTasksCache.find(lt => lt.fecha === newTask.fecha && cleanTaskId(lt.id) === cleanTaskId(newTask.id));
                  if (localTask) {
                      if (localTask._dirty) {
                          return localTask; // OFFLINE-FIRST: Proteger cambios no guardados
                      }
                      if ((!newTask.items || newTask.items.length === 0) && localTask.items && localTask.items.length > 0) {
                          return { ...newTask, items: localTask.items }; // Preservar detalle local
                      }
                  }
                  return newTask;
              });
              
              let migratedSynced = false;
              almacenajeTasksCache = almacenajeTasksCache.map(t => {
    if (t && t.status === 'Auditado') { t.status = 'Finalizado'; t.audited = true; }
                  if (t && t.id && !t.id.includes('_')) {
                      t.id = `${t.fecha}_${t.id}`;
                      migratedSynced = true;
                  }
                  return t;
              });
              if (migratedSynced) {
                  // Por `guardarBloqueFusionado`, que relee del servidor antes de escribir.
                  // Subir el bloque entero desde acá pisaría lo que otra PC haya hecho: es la
                  // misma vía que rompió la noche del 07-ago-2026 desde el reenvío de pendientes.
                  // Solo se migran los ids sin fecha; el resto de cada tarea queda como está.
                  setTimeout(() => guardarBloqueFusionado(base => base.map(t => {
                      if (t && t.id && !String(t.id).includes('_')) t.id = `${t.fecha}_${t.id}`;
                      if (t && t.status === 'Auditado') { t.status = 'Finalizado'; t.audited = true; }
                      return t;
                  })).catch(e => console.warn('[MIGRACIÓN] no se pudo guardar:', e && e.message)), 200);
              }
              
              if (syncedTasks.length === 0 && almacenajeTasksCache.length > 0) {
                  console.log("🧹 [PULL] Sincronización de borrado total desde la nube.");
                  almacenajeTasksCache = [];
              }
          }
          safeSaveAlmacenajeTasksCache();
      }
      updateSyncIndicator('online', `SISTEMA v${VERSION} ONLINE`);
  } catch (e) { 
      console.error("[SYNC] Error al cargar:", e);
      updateSyncIndicator('offline', 'MODO OFFLINE ACTIVO');
  }
};

/**
 * Sub-pestañas de Almacenaje que dibuja renderAlmacenajeTareas. Productividad y
 * Config. Tareas comparten el MISMO contenedor, así que un repintado automático que no
 * mire esto les pinta encima: la pestaña quedaba marcada en Productividad y abajo se veía
 * el KPI, sin que el usuario hubiera tocado nada.
 */
const SUBTABS_DE_TAREAS = ['tareas_dia', 'kpi_tareas'];
const tareasEsLaVistaActiva = () => SUBTABS_DE_TAREAS.includes(localStorage.getItem('activeSub_almacenaje'));

/**
 * RADAR: lo que hace que una PC vea lo que otra acaba de hacer.
 *
 * ANTES TARDABA HASTA 90 SEGUNDOS, y no por la red. Eran dos relojes que no se hablaban:
 * este radar corría cada 60 s y llamaba a `initializeAdminData()` SIN forzar — y esa
 * función, después de la primera carga, devuelve el store tal como está y no le pregunta
 * nada al servidor (`if (isFirstPullDone && !force) return syncStore`). Lo único que
 * bajaba datos era el `setInterval(pullGlobal, 30000)` del motor, por su cuenta. Así que
 * un cambio esperaba hasta 30 s a que alguien lo bajara y hasta 60 s más a que este radar
 * se asomara a mirar: hasta minuto y medio.
 *
 * Lo midió Daniel el 06-ago-2026 con el turno adentro: el asistente asignaba dos tareas y
 * en la otra PC no aparecían; tuvo que forzar la actualización a mano. La red no tenía
 * nada que ver — el área entera son 1,4 MB y baja en 2 segundos.
 *
 * FORZAR ES BARATO. `pullGlobal` pregunta primero por las versiones (2 KB, medio segundo)
 * y solo descarga las áreas cuya marca cambió. Preguntar cada 20 s cuesta esos 2 KB; el
 * 1,4 MB se baja únicamente cuando de verdad hay algo nuevo.
 */
let __versionTareasPintada = null;
/**
 * Que dos vueltas no se pisen. A 60 s sobraba tiempo para terminar; a 20 s, con la red del
 * trabajo lenta o el servidor recién despierto, una vuelta puede no haber vuelto cuando
 * entra la siguiente. Sin esto se encimarían descargas y cada una repintaría la pantalla.
 */
let __radarOcupado = false;

setInterval(async () => {
    if (document.visibilityState === 'visible') {
        if (__radarOcupado) { console.log("📡 [RADAR v24] La vuelta anterior sigue en curso; se saltea esta."); return; }
        __radarOcupado = true;
        try {
        console.log("📡 [RADAR v24] Buscando actualizaciones en la nube...");
        await adminService.initializeAdminData(true);
        // Solo refrescar si estamos en la pestaña de almacenaje y no hay cambios pendientes locales
        const currentTab = ((document.querySelector('.nav-item.active') || {}).dataset || {}).id;
        if (currentTab === 'almacenaje') {
            const synced = adminService.adminStore.almacenaje_tasks;
            // SE COMPARA LA MARCA DEL ÁREA, NO EL CONTENIDO. Acá se stringificaban las dos
            // listas enteras en cada vuelta —varios MB, dos veces— solo para saber si había
            // algo nuevo. A 60 s se notaba poco; a 20 s trabaría la pantalla. La marca la
            // deja el motor al aplicar el área y cambia con cualquier escritura del servidor.
            // Si no está —servidor viejo, o área que todavía no se aplicó— se cae a la
            // comparación de antes, que es lenta pero nunca se pierde un cambio.
            const versionArea = ((window._pulseSyncState || {}).versiones || {})['almacenaje_tasks'];
            const hayAlgoNuevo = versionArea
                ? versionArea !== __versionTareasPintada
                : JSON.stringify(synced) !== JSON.stringify(almacenajeTasksCache);
            // CON UNA VENTANA ABIERTA, EL RADAR NO TOCA NADA.
            //
            // Acá se perdían las asignaciones (Daniel, 10-ago-2026). Abajo se reemplaza
            // `almacenajeTasksCache` por objetos nuevos, y el modal que esté abierto quedó
            // apuntando a los viejos: lo que el asistente escriba va a una ficha suelta que
            // ya no está en la lista, así que no se ve ni se guarda con el resto.
            //
            // No se marca `__versionTareasPintada`, a propósito: el área sigue contando como
            // no pintada y la vuelta siguiente —20 segundos— la aplica. Solo se posterga,
            // nunca se pierde. Y mientras tanto no hay nada que ver: la ventana tapa la tabla.
            if (hayModalDeTareaAbierto()) {
                console.log('📡 [RADAR v24] Hay una ventana de tarea abierta: no se toca la lista hasta que se cierre.');
                return;
            }

            if (synced && hayAlgoNuevo) {
                __versionTareasPintada = versionArea;
                console.log("✨ [RADAR v24] Datos nuevos detectados. Aplicando Fusión Híbrida.");
                
                // SOLO SE EXIGE QUE LA NUBE TENGA DATOS. NO QUE TENGA MÁS QUE ESTA PC.
                //
                // Acá decía `synced.length >= almacenajeTasksCache.length`, y esa condición
                // hacía que la pantalla NO PUDIERA VER NUNCA UNA ELIMINACIÓN. Si el servidor
                // quedaba con menos registros que la copia local, el radar los rechazaba en
                // silencio y esta PC se quedaba con los viejos para siempre.
                //
                // Lo pagó Daniel el 07-ago-2026: al limpiar 15 tareas duplicadas, el área
                // pasó a tener menos registros, su pantalla rechazó la actualización, y el
                // papel salió con la Tarea47 —cerrada en el servidor hacía rato— repitiendo
                // los artículos de otra. El código del papel estaba bien; le estaban dando
                // datos viejos.
                //
                // La protección que sí hacía falta se queda: si la nube devuelve VACÍO, no se
                // borra lo local. Eso cubre el caso real —una respuesta fallida— sin bloquear
                // los legítimos.
                if (synced && synced.length > 0) {
                    almacenajeTasksCache = synced.map(newTask => {
                        const localTask = almacenajeTasksCache.find(lt => lt.id === newTask.id);
                        if (localTask) {
                            if (localTask._dirty) {
                                return localTask; // OFFLINE-FIRST: Proteger cambios no guardados
                            }
                            if ((!newTask.items || newTask.items.length === 0) && localTask.items && localTask.items.length > 0) {
                                return { ...newTask, items: localTask.items };
                            }
                        }
                        return newTask;
                    });
                } else {
                    console.log("📡 [RADAR] Nube sin datos. Manteniendo PC local como fuente de verdad.");
                }

                // Solo se repinta si el usuario está viendo Tareas Día o KPI. En
                // Productividad o Config. Tareas, los datos igual quedaron actualizados en
                // memoria: se verán cuando vuelva, sin arrebatarle la pantalla.
                const areaContent = document.getElementById('areaContent');
                if (areaContent && tareasEsLaVistaActiva()) {
                    const _sy = window.scrollY;
                    renderAlmacenajeTareas(areaContent);
                    requestAnimationFrame(() => window.scrollTo({ top: _sy, behavior: 'instant' }));
                }
            }
        }
        } finally { __radarOcupado = false; }
    }
    // Cada 20 s, no cada 60. Dos personas repartiendo hojas del mismo turno necesitan verse
    // en segundos, no en minutos; y con la consulta de versiones cada vuelta cuesta 2 KB.
}, 20000);
    
const restoreAdminDataFromLocal = async () => {
    try {
        updateSyncIndicator('working', 'RESTAURANDO DATOS...');
        const keys = ['workers', 'permissions', 'users', 'attendance'];
        let count = 0;
        for (const key of keys) {
            const stored = localStorage.getItem(`logistics_sync_v24_${key}`);
            if (stored) {
                const data = JSON.parse(stored);
                if (data && (Array.isArray(data) ? data.length > 0 : Object.keys(data).length > 0)) {
                    await adminService.save(key, data);
                    count++;
                }
            }
        }
        alert(`✅ ¡Éxito! Se han restaurado ${count} módulos de administración desde tu PC.`);
        location.reload();
    } catch (e) {
        alert("❌ Error al restaurar: " + e.message);
        updateSyncIndicator('online', `SISTEMA v${VERSION} ONLINE`);
    }
};
window.restoreAdminDataFromLocal = restoreAdminDataFromLocal;

