const API_BASE = 'https://logistics-backend-wv0x.onrender.com/api';
let currentChart = null;
let lastBufferKPI = null;
let bufferConfigCached = null;
let lastBufferResult = null;
let activeAnalisisSub = 'articulo_temp';
let activeConfigSub = 'parametros';

// ── Cache de resultados Replenishment (scope de módulo, igual que lastBufferResult) ──
let _replCache = (() => {
  try {
    const _c = localStorage.getItem('logistics_v24_prod_replCache');
    if (!_c) return null;
    const parsed = JSON.parse(_c);
    // descomprimir items si vienen en formato comprimido
    if (parsed && Array.isArray(parsed.items) && parsed.items.length && parsed.items[0].s !== undefined) {
      parsed.items = parsed.items.map(i => ({
        sku: i.s, art7: i.a, talla: i.t, marcas: i.m, genderRims: i.g,
        temporada: i.T, qAct: i.qA, qRes: i.qR,
        estado: i.e, prioridad: i.p, factor: i.f !== undefined ? i.f : parsed.umbral,
        // Un caché guardado antes del llenado por cuerpo no los trae. Se dejan sin definir
        // a propósito: aBajarDe() cae solo al cálculo por factor cuando falta 'aBajar'.
        aBajar: i.b, relleno: i.rl
      }));
    }
    return parsed;
  } catch(e) { return null; }
})();

window.downloadExcelDetail = async () => {
    if (!lastBufferResult) return;
    
    // 0. Copia profunda para evitar mutaciones de estado en sucesivas descargas
    const data = JSON.parse(JSON.stringify(lastBufferResult));

    // 1. Obtener la configuración del buffer guardada
    let savedQtys = {};
    try {
        const config = await fetchBufferConfig();
        if (config && config.brand_gender_qtys) {
            savedQtys = JSON.parse(config.brand_gender_qtys) || {};
        }
    } catch (e) {
        console.warn("[PULSE] Error fetching/parsing buffer config for excel:", e);
    }

    // 2. Construir maestroMap con detección robusta de columnas
    const maestroMap = new Map();
    if (dataStore.articulos) {
        let brandIdx = 13;
        let genderIdx = 3;
        const firstRow = dataStore.articulos[0];
        if (firstRow && Array.isArray(firstRow)) {
            firstRow.forEach((cell, idx) => {
                const cellStr = String(cell || '').trim().toUpperCase();
                if (cellStr === 'MARCA' || cellStr === 'BRAND') {
                    brandIdx = idx;
                } else if (cellStr === 'GENDER RIMS' || cellStr === 'GENDER' || cellStr === 'GENDERRIMS' || cellStr === 'DEPARTAMENTO' || cellStr === 'GENERO') {
                    genderIdx = idx;
                }
            });
        }
        
        let startIndex = 0;
        if (Array.isArray(dataStore.articulos[0])) {
            const firstCell = String(dataStore.articulos[0][0] || '').trim().toUpperCase();
            if (firstCell.includes('SKU') || firstCell.includes('ARTICULO') || firstCell.includes('BARCODE') || firstCell.includes('CODIGO') || firstCell.includes('GENDER') || firstCell.includes('GENERO') || firstCell.includes('MARCA') || firstCell.includes('BRAND')) {
                startIndex = 1;
            }
        }

        for (let i = startIndex; i < dataStore.articulos.length; i++) {
            const row = dataStore.articulos[i];
            if (!row) continue;
            const raw = Array.isArray(row) ? row : Object.values(row);
            if (raw.length <= Math.max(brandIdx, genderIdx)) continue;
            
            const art7 = String(raw[1] || '').trim().substring(0, 7);
            const marca = String(raw[brandIdx] || 'OTROS').trim().toUpperCase();
            const gender = String(raw[genderIdx] || 'OTROS').trim().toUpperCase();
            
            if (art7 && !maestroMap.has(art7)) {
                maestroMap.set(art7, { marca, gender });
            }
        }
    }

    // [OPTIMIZACIÓN SOLUCIÓN 1]
    // La redistribución manual y ad-hoc que se hacía aquí ha sido eliminada por completo.
    // Ahora las cantidades de buffer extra configuradas se integran directamente en el motor 
    // de cálculo central (calculateBufferPallets), garantizando que las LPNs en reserva se
    // busquen, seleccionen y descuenten con absoluta precisión matemática desde el origen.
    // Esto asegura coherencia total entre la interfaz de usuario, las alertas de stock y los reportes descargados.

    const workbook = new ExcelJS.Workbook();

    // --- PESTAÑA 1: MONTACARGA (FORMATO PREMIUM) ---
    const wsMonta = workbook.addWorksheet('Montacarga', { 
        properties: { tabColor: { argb: 'FFADD8E6' } },
        pageSetup: { printTitlesRow: '1:4', orientation: 'portrait' } 
    });
    
    wsMonta.columns = [
        { key: 'n', width: 12 }, { key: 'ubi', width: 21.3 }, { key: 'lpn', width: 30 }, { key: 'qty', width: 18 }
    ];

    wsMonta.mergeCells('A1:D1');
    const row1 = wsMonta.getRow(1);
    row1.getCell(1).value = 'MONTACARGA';
    row1.getCell(1).font = { size: 48, bold: true, name: 'Calibri' };
    row1.getCell(1).alignment = { vertical: 'middle', horizontal: 'center' };

    wsMonta.mergeCells('A2:D2');
    const row2 = wsMonta.getRow(2);
    row2.getCell(1).value = data.timestamp || new Date().toLocaleString();
    row2.getCell(1).font = { size: 10, name: 'Calibri' };
    row2.getCell(1).alignment = { vertical: 'middle', horizontal: 'center' };

    const row4M = wsMonta.getRow(4);
    row4M.values = ["N° Paletas", "UBICACIÓN", "LPN", "QTY RESERVA"];
    row4M.font = { bold: true, size: 14, name: 'Calibri' };
    row4M.eachCell((cell, colNumber) => {
        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
        if (colNumber === 1 || colNumber === 4) cell.alignment = { horizontal: 'center' };
    });

    // Crear un conjunto de LPNs válidos con demanda real (QTY BUFFER > 0)
    const lpnsWithDemand = new Set();
    if (Array.isArray(data.detalle)) {
        data.detalle.forEach(d => {
            if ((d['QTY BUFFER'] || 0) > 0 && d.LPN) {
                lpnsWithDemand.add(d.LPN);
            }
        });
    }

    // Filtrar physicalDetalle para incluir únicamente LPNs que tienen demanda real asignada
    const physicalDetalle = (data.detalle || [])
        .filter(d => String(d.UBICACIONES || '').startsWith('SEL-') && lpnsWithDemand.has(d.LPN))
        .sort((a, b) => a.UBICACIONES.localeCompare(b.UBICACIONES));

    const montacargaMap = new Map();
    physicalDetalle.forEach(d => {
        const lpn = d.LPN;
        if (!montacargaMap.has(lpn)) montacargaMap.set(lpn, { ubi: d.UBICACIONES, lpn: lpn, qty: 0 });
        montacargaMap.get(lpn).qty += d['QTY RESERVA'];
    });

    const montacargaRows = Array.from(montacargaMap.values()).sort((a, b) => a.ubi.localeCompare(b.ubi));
    montacargaRows.forEach((r, idx) => {
        const row = wsMonta.addRow([idx + 1, r.ubi, r.lpn, r.qty]);
        row.font = { size: 14, name: 'Calibri' };
        row.eachCell((cell, colNumber) => {
            cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
            if (colNumber === 1 || colNumber === 4) cell.alignment = { horizontal: 'center' };
        });
    });

    // --- PESTAÑA 2: ANÁLISIS BUFFER (FORMATO PREMIUM) ---
    const wsAnalisis = workbook.addWorksheet('Análisis Buffer', {
        properties: { tabColor: { argb: 'FF22C55E' } }, // VERDE SOLICITADO
        pageSetup: { 
            printTitlesRow: '1:4',
            margins: { left: 0, right: 0, top: 0.5, bottom: 0, header: 0.3, footer: 0 },
            fitToPage: true,
            fitToWidth: 1,
            fitToHeight: 0
        }
    });

    // Poner N° página en el centro de la cabecera
    wsAnalisis.headerFooter = {
        oddHeader: "&C Página &P de &N",
        evenHeader: "&C Página &P de &N"
    };
    wsAnalisis.columns = [
        { key: 'ubi', width: 32 },
        { key: 'lpn', width: 30 },
        { key: 'sku', width: 25 },
        { key: 'talla', width: 12 },
        { key: 'marca', width: 22 },
        { key: 'gender', width: 25 },
        { key: 'act', width: 18 },
        { key: 'res', width: 18 },
        { key: 'buf', width: 18 },
        // J va vacía a propósito: separa el detalle del REPORTE PALETAS, que arranca en la K
        // y se filtra por su cuenta sin arrastrar las filas del detalle.
        { key: 'sep', width: 4 },
        { key: 'p_nro', width: 8 },
        { key: 'p_ubi', width: 32 },
        { key: 'p_lpn', width: 30 },
        { key: 'p_cant', width: 16 },
        { key: 'p_buf', width: 16 },
        { key: 'p_pct', width: 16 }
    ];

    wsAnalisis.mergeCells('A1:I1');
    const row1A = wsAnalisis.getRow(1);
    row1A.height = 60;
    row1A.getCell(1).value = 'ANÁLISIS BUFFER';
    row1A.getCell(1).font = { size: 48, bold: true, name: 'Calibri' };
    row1A.getCell(1).alignment = { vertical: 'middle', horizontal: 'center' };

    wsAnalisis.mergeCells('A2:I2');
    const row2A = wsAnalisis.getRow(2);
    row2A.height = 30;
    row2A.getCell(1).value = data.timestamp || new Date().toLocaleString();
    row2A.getCell(1).font = { size: 10, name: 'Calibri' };
    row2A.getCell(1).alignment = { vertical: 'middle', horizontal: 'center' };

    const row3A = wsAnalisis.getRow(3);
    row3A.height = 30;

    const row4A = wsAnalisis.getRow(4);
    row4A.values = ["UBICACIÓN", "LPN", "SKU", "TALLAS", "MARCAS", "GENDER RIMS", "CANTIDAD", "RESERVA", "BUFFER"];
    row4A.height = 21;
    row4A.font = { bold: true, color: { argb: 'FFFFFFFF' }, size: 16, name: 'Calibri' };
    row4A.eachCell(cell => {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF000000' } };
        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
        cell.alignment = { vertical: 'middle', horizontal: 'left' };
    });
    [7, 8, 9].forEach(c => row4A.getCell(c).alignment = { vertical: 'middle', horizontal: 'center' });

    // maestroMap ya fue construido robustamente al inicio de la función
    const tallasMap = Array.isArray(dataStore.tabla_tallas) ? dataStore.tabla_tallas.reduce((acc, x) => { acc[x.sku] = x.talla; return acc; }, {}) : (dataStore.tabla_tallas || {});

    /**
     * CUÁNTO DE CADA PALETA SE BAJA.
     *
     * Una fila por LPN, no por talla: la paleta se mueve entera o no se mueve, y lo que
     * hace falta saber al planificar es si se vacía o si vuelve arriba con lo que sobró.
     * Tres tallas con 100 en reserva y 100 al buffer cada una son 300 sobre 300: baja al
     * 100%. Con esto se puede filtrar cuántas paletas salen completas y cuántas a medias.
     */
    const porPaleta = new Map();
    physicalDetalle.forEach(d => {
        const lpn = String(d.LPN || '').trim();
        if (!lpn) return;
        if (!porPaleta.has(lpn)) porPaleta.set(lpn, { ubi: d.UBICACIONES || '', reserva: 0, buffer: 0 });
        const p = porPaleta.get(lpn);
        p.reserva += (d['QTY RESERVA'] || 0);
        p.buffer  += (d['QTY BUFFER']  || 0);
    });

    let lastUbi = "", uSumA = 0, uSumR = 0, uSumB = 0;
    let gSumA = 0, gSumR = 0, gSumB = 0;

    physicalDetalle.forEach((d) => {
        if (lastUbi !== "" && d.UBICACIONES !== lastUbi) {
            const totalRow = wsAnalisis.addRow([`TOTAL ${lastUbi}`, "", "", "", "", "", uSumA, uSumR, uSumB]);
            totalRow.height = 21;
            totalRow.font = { bold: true, size: 16, name: 'Calibri' };
            totalRow.eachCell(cell => {
                cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFA6A6A6' } }; // Gris 35%
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                cell.alignment = { vertical: 'middle' };
            });
            [7, 8, 9].forEach(c => totalRow.getCell(c).alignment = { vertical: 'middle', horizontal: 'center' });
            uSumA = 0; uSumR = 0; uSumB = 0;
        }

        const sku = d.SKU;
        const art7 = sku.substring(0, 7);
        const maestro = maestroMap.get(art7) || { marca: '-', gender: '-' };
        
        // Extracción directa de talla desde la descripción del artículo (ej: -1-28, -2-37.5)
        let talla = '-';
        const rawDesc = d.DESCRIPCION || d.Descrip || d.Descripcion || d.description || '';
        
        if (rawDesc) {
            // Patrón estricto: guion + dígito 1-9 + guion + talla al final (ej: -1-28)
            const regexPatron = /-([1-9])-([A-Z0-9.\u00c1\u00c9\u00cd\u00d3\u00da\u00d1]+)$/i;
            const match = String(rawDesc).trim().match(regexPatron);
            if (match) {
                talla = match[2].trim();
            } else {
                // Fallback con validación: solo tomar el último segmento si el penúltimo es dígito 1-9
                const parts = String(rawDesc).trim().split('-');
                if (parts.length >= 3) {
                    const preLast = parts[parts.length - 2].trim();
                    if (preLast.length === 1 && preLast >= '1' && preLast <= '9') {
                        talla = parts[parts.length - 1].trim();
                    }
                }
            }
        }
        
        // Si no se pudo extraer por descripción o tiene valores inválidos, usar mapeo de base de datos
        const numTalla = parseFloat(talla);
        if (talla === '-' || isNaN(numTalla) || numTalla > 55 || numTalla < 1) {
            talla = tallasMap[sku] || '-';
            const numMap = parseFloat(talla);
            if (talla === '-' || isNaN(numMap) || numMap > 55 || numMap < 1) {
                // Fallback final: extraer del SKU sin reglas matemáticas
                const segments = sku.split('-');
                if (segments.length >= 3) {
                    talla = segments[segments.length - 1].trim();
                }
            }
        }

        const dataRow = wsAnalisis.addRow([
            d.UBICACIONES !== lastUbi ? d.UBICACIONES : "",
            d.LPN, sku, talla, maestro.marca, maestro.gender,
            d['QTY ACTIVO'], d['QTY RESERVA'], d['QTY BUFFER']
        ]);
        dataRow.height = 21;
        dataRow.font = { size: 16, name: 'Calibri' };
        dataRow.eachCell((cell, colNumber) => {
            cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
            cell.alignment = { vertical: 'middle' };
            if (colNumber >= 7) cell.alignment = { vertical: 'middle', horizontal: 'center' };
        });

        uSumA += (d['QTY ACTIVO'] || 0); uSumR += (d['QTY RESERVA'] || 0); uSumB += (d['QTY BUFFER'] || 0);
        gSumA += (d['QTY ACTIVO'] || 0); gSumR += (d['QTY RESERVA'] || 0); gSumB += (d['QTY BUFFER'] || 0);
        lastUbi = d.UBICACIONES;
    });

    if (lastUbi !== "") {
        const lastTotal = wsAnalisis.addRow([`TOTAL ${lastUbi}`, "", "", "", "", "", uSumA, uSumR, uSumB]);
        lastTotal.height = 21;
        lastTotal.font = { bold: true, size: 16, name: 'Calibri' };
        lastTotal.eachCell(cell => {
            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFA6A6A6' } };
            cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
            cell.alignment = { vertical: 'middle' };
        });
        [7, 8, 9].forEach(c => lastTotal.getCell(c).alignment = { vertical: 'middle', horizontal: 'center' });
    }
    wsAnalisis.addRow([]);
    const gtRow = wsAnalisis.addRow(["TOTAL GENERAL", "", "", "", "", "", gSumA, gSumR, gSumB]);
    gtRow.height = 21;
    gtRow.font = { bold: true, size: 16, color: { argb: 'FFFFFFFF' }, name: 'Calibri' };
    gtRow.eachCell(cell => {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF000000' } };
        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
        cell.alignment = { vertical: 'middle' };
    });
    [7, 8, 9].forEach(c => gtRow.getCell(c).alignment = { vertical: 'middle', horizontal: 'center' });

    // ══════════════════════════════════════════════════════════════════════════════════
    // REPORTE PALETAS — al costado del detalle, de la K a la O
    //
    // El detalle de la izquierda va talla por talla y sirve para armar la bajada. Este es
    // otro corte del mismo dato: UNA FILA POR PALETA, para poder ordenar y filtrar cuáles
    // salen completas y cuáles a medias sin arrastrar las filas del detalle.
    //
    // Va en la misma hoja y no en una pestaña aparte porque se lee junto con el detalle.
    // La J queda vacía para que Excel los trate como dos bloques distintos: así el filtro
    // de este no toca al otro.
    // ══════════════════════════════════════════════════════════════════════════════════
    wsAnalisis.mergeCells('K2:P2');
    const tituloPal = wsAnalisis.getCell('K2');
    tituloPal.value = 'REPORTE PALETAS';
    tituloPal.font = { bold: true, size: 20, name: 'Calibri' };
    tituloPal.alignment = { vertical: 'middle', horizontal: 'center' };

    // La misma marca de tiempo que el encabezado grande: es la del momento en que se
    // procesó el buffer, no la de cuando se abre el archivo. Impresa y sin fecha, dos
    // corridas del mismo día se confunden entre sí.
    wsAnalisis.mergeCells('K3:P3');
    const fechaPal = wsAnalisis.getCell('K3');
    fechaPal.value = data.timestamp || new Date().toLocaleString();
    fechaPal.font = { size: 10, name: 'Calibri' };
    fechaPal.alignment = { vertical: 'middle', horizontal: 'center' };

    const CAB_PAL = ['N°', 'UBICACIÓN', 'LPN', 'CANTIDAD', 'BUFFER', '% PALETA'];
    CAB_PAL.forEach((txt, i) => {
        const c = wsAnalisis.getRow(4).getCell(11 + i);
        c.value = txt;
        c.font = { bold: true, color: { argb: 'FFFFFFFF' }, size: 16, name: 'Calibri' };
        c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF000000' } };
        c.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
        c.alignment = { vertical: 'middle', horizontal: (i === 1 || i === 2) ? 'left' : 'center' };
    });

    // Las que más se vacían arriba: son las que conviene bajar primero. El número queda
    // pegado a ESE orden y no se renumera al filtrar, así "la paleta 12" es siempre la misma.
    const paletasOrdenadas = [...porPaleta.entries()]
        .map(([lpn, p]) => ({ lpn, ...p, pct: p.reserva > 0 ? p.buffer / p.reserva : 0 }))
        .sort((a, b) => b.pct - a.pct || b.buffer - a.buffer);

    let totPalReserva = 0, totPalBuffer = 0;
    paletasOrdenadas.forEach((p, idx) => {
        const fila = wsAnalisis.getRow(5 + idx);
        const vals = [idx + 1, p.ubi, p.lpn, p.reserva, p.buffer, p.pct];
        vals.forEach((v, i) => {
            const c = fila.getCell(11 + i);
            c.value = v;
            c.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
            c.alignment = { vertical: 'middle', horizontal: (i === 1 || i === 2) ? 'left' : 'center' };
            // Sale impreso en blanco y negro, así que la paleta que se vacía entera se
            // distingue con NEGRITA y no con color: el relleno no sobrevive a la impresión.
            c.font = { size: 16, name: 'Calibri', bold: p.pct >= 1 };
        });
        fila.getCell(16).numFmt = '0%';
        if (fila.height < 21) fila.height = 21;
        totPalReserva += p.reserva;
        totPalBuffer  += p.buffer;
    });

    if (paletasOrdenadas.length) {
        const ultima = 4 + paletasOrdenadas.length;
        wsAnalisis.autoFilter = { from: { row: 4, column: 11 }, to: { row: ultima, column: 16 } };

        // El cierre va DESPUÉS de una fila vacía: pegado al listado, el filtro de arriba se
        // lo llevaría puesto y al filtrar por "solo las de 100%" el total desaparecería.
        const filaTot = wsAnalisis.getRow(ultima + 2);
        const pctGlobal = totPalReserva > 0 ? totPalBuffer / totPalReserva : 0;
        const valsTot = [paletasOrdenadas.length, 'PALETAS A BAJAR', '', totPalReserva, totPalBuffer, pctGlobal];
        valsTot.forEach((v, i) => {
            const c = filaTot.getCell(11 + i);
            c.value = v;
            c.font = { bold: true, size: 16, color: { argb: 'FFFFFFFF' }, name: 'Calibri' };
            c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF000000' } };
            c.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
            c.alignment = { vertical: 'middle', horizontal: i === 1 ? 'left' : 'center' };
        });
        wsAnalisis.mergeCells(filaTot.number, 12, filaTot.number, 13);   // "PALETAS A BAJAR"
        filaTot.getCell(16).numFmt = '0%';
        filaTot.height = 21;
    }

    // --- OTRAS PESTAÑAS ---
    const addStandardSheet = (name, jsonData, tabColor = null) => {
        if (!jsonData || jsonData.length === 0) return;
        const ws = workbook.addWorksheet(name, { properties: { tabColor: tabColor ? { argb: tabColor } : undefined } });
        const keys = Object.keys(jsonData[0] || {});
        ws.columns = keys.map(k => ({ header: k, key: k, width: 20 }));
        ws.addRows(jsonData);
        ws.getRow(1).font = { bold: true };
        ws.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFEEEEEE' } };
    };

    addStandardSheet('Detalle', data.resumenSKUDetalle);
    addStandardSheet('Sku Bajar', (data.resumenSKUDetalle || []).filter(s => s.Diferencia > 0));
    addStandardSheet('Fantasma SKU', data.resumenSKUDetalle, 'FFFF0000'); // Pestaña roja
    
    addStandardSheet('LPN Selecionados', physicalDetalle.map(d => ({
        'Ubicacion': d.UBICACIONES, 'LPN': d.LPN, 'Sku': d.SKU, 'Stock Activo': d['QTY ACTIVO'],
        'Stock Reserva': d['QTY RESERVA'], 'Qty Buffer': d['QTY BUFFER'], 'Articulo': d.Articulo
    }))); // Sin color para evitar confusión

    addStandardSheet('Tallas', Object.entries(tallasMap).map(([sku, talla]) => ({ 'SKU': sku, 'TALLA': talla })));
    addStandardSheet('Detalle Zonas', (data.detalleZonas || []).filter(d => d['NIVEL/AREA'] !== '7. SIN STOCK'));
    addStandardSheet('RQ Revisar', data.detalleRQRevisar);
    addStandardSheet('Sin Stock', (data.detalleZonas || []).filter(d => d['NIVEL/AREA'] === '7. SIN STOCK').map(d => ({
        'NIVEL/AREA': d['NIVEL/AREA'], 'ARTÍCULO': d['ARTÍCULO'], 'SKU': d['SKU'], 'ATD RQ': d['ATD RQ']
    })));
    addStandardSheet('Sin Stock por Revisar', data.sinStockPorRevisar);

    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Detalle_Buffer_Completo_${getLogicalDate()}.xlsx`;
    a.click();
    window.URL.revokeObjectURL(url);
};

window.downloadExcelZonas = () => {
    alert("⚠️ Este reporte ahora está integrado en 'EXCEL DETALLE'.");
};

const formatDateTime = (isoStr) => {
    if (!isoStr || isoStr === '---' || isoStr === 'null') return '---';
    try {
        const date = new Date(isoStr);
        if (isNaN(date.getTime())) return isoStr;
        const dd = String(date.getDate()).padStart(2, '0');
        const mm = String(date.getMonth() + 1).padStart(2, '0');
        const yyyy = date.getFullYear();
        const hh = String(date.getHours()).padStart(2, '0');
        const min = String(date.getMinutes()).padStart(2, '0');
        const ss = String(date.getSeconds()).padStart(2, '0');
        return `${dd}/${mm}/${yyyy} ${hh}:${min}:${ss}`;
    } catch (e) {
        return isoStr;
    }
};

